function fitHeaderNotification(host,text){if(!host)return;const span=host.querySelector('.header-notification-text');if(!span)return;host.classList.toggle('short-message',String(text||'').length<=52);host.classList.toggle('long-message',String(text||'').length>52);host.classList.remove('notification-clamped');span.style.removeProperty('font-size');requestAnimationFrame(()=>{let size=13.5;const min=10.5;span.style.setProperty('font-size',size+'px','important');const fits=()=>span.scrollWidth<=span.clientWidth+1;while(!fits()&&size>min){size=Math.max(min,size-.5);span.style.setProperty('font-size',size+'px','important')}host.classList.toggle('notification-clamped',!fits())})}
function hideToast(host=$('#header-notification')){if(!host)return;host.className='header-notification';host.dataset.tone='';host.innerHTML='';host.title='';host.style.removeProperty('font-size');host.setAttribute('aria-hidden','true');host.setAttribute('aria-live','polite')}
function toast(title,msg='',tone=''){const host=$('#header-notification');if(!host)return;const inferred=tone||(/failed|error|could not|offline/i.test(title+' '+msg)?'error':/warning|reconnecting|risk|fallback|degraded/i.test(title+' '+msg)?'warning':/saved|complete|selected|restored|connected/i.test(title+' '+msg)?'success':'info'),text=[title,msg].filter(Boolean).join(' · '),ttl=({success:3800,info:6500,warning:9500,error:12500})[inferred]||6500;clearTimeout(window.__headerAlertTimer);host.className=`header-notification ${inferred}`;host.dataset.tone=inferred;host.innerHTML=`<span class="header-notification-text">${brandInline(text)}</span>`;host.title=text;host.setAttribute('aria-hidden','false');host.setAttribute('aria-live',inferred==='error'?'assertive':'polite');fitHeaderNotification(host,text);window.__headerAlertTimer=setTimeout(()=>hideToast(host),ttl)}
async function api(path,body){const opt=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)};const r=await fetch(path,opt);const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||`Request failed (${r.status})`);return data}
async function openExternalURL(raw){const url=String(raw||'').trim();if(!/^https?:\/\//i.test(url)){toast('Could Not Open Link','Only http/https links are supported.','error');return}try{await api('/api/app/open-url',{url})}catch(e){toast('Could Not Open Link',e.message,'error')}}
