function allSymbols(){const desks=['swing','day','long'].flatMap(k=>deskWL(k).symbols||[]),discovery=getWL(state?.settings?.discoveryWatchlistId||'discovery').symbols||[];return [...new Set([...COMMON_MARKET_SYMBOLS,...desks,...discovery])];}
function normalizeWL(w,id='',name='Empty'){const obj=(w&&typeof w==='object')?w:{};return {id:String(obj.id||id||''),name:String(obj.name||name||'Empty'),symbols:Array.isArray(obj.symbols)?obj.symbols.filter(Boolean):[]}}
function getWL(id){const list=Array.isArray(state?.watchlists)?state.watchlists.filter(w=>w&&typeof w==='object'):[];const wanted=String(id||'');const found=list.find(w=>String(w.id||'')===wanted);return normalizeWL(found,wanted,wanted==='discovery'?'Discovery Watchlist':'Empty')}
function deskWL(kind){const id=state?.settings?.[deskCfg[kind].listKey]||kind;return normalizeWL(getWL(id),id,deskCfg[kind].title+' Watchlist')}
