function ageText(ms){if(!Number.isFinite(ms))return 'Unknown age';if(ms<1000)return `${Math.max(0,Math.round(ms))} ms`;if(ms<60000)return `${(ms/1000).toFixed(ms<10000?1:0)}s`;return `${Math.floor(ms/60000)}m ${Math.round((ms%60000)/1000)}s`}
