function quoteVersion(sym){const x=q(sym);return [num(x.providerTimestamp)||num(x.updatedAt),num(x.price).toFixed(6),num(x.bid).toFixed(6),num(x.ask).toFixed(6),num(x.sessionClose).toFixed(6),String(x.source||''),String(x.dataState||'')].join(':')}
function analysisQuoteVersion(sym){const x=q(sym);return [num(x.price).toFixed(6),num(x.open).toFixed(6),num(x.previousClose).toFixed(6)].join(':')}
