function barVersion(sym,key){const bs=bars(sym,key),b=bs.at(-1)||{};return `${bs.length}:${num(b.t)}:${num(b.c).toFixed(6)}:${num(b.v).toFixed(0)}`}
function fundamentalVersion(sym){const f=runtime?.fundamentals?.[sym]||{};return `${num(f.updatedAt)}:${num(f.revenueGrowth).toFixed(4)}:${num(f.epsGrowth).toFixed(4)}:${num(f.roe).toFixed(4)}:${num(f.netMargin).toFixed(4)}:${num(f.debtToEquity).toFixed(4)}`}
function earningsVersion(sym){return (runtime?.earnings||[]).filter(x=>String(x.symbol||'').toUpperCase()===String(sym||'').toUpperCase()).map(x=>`${x.date||''}:${x.hour||''}`).sort().join('|')}
function regimeInputSignature(kind){if(kind==='day'){const part=sym=>bars(sym,'intraday').length>=4?barVersion(sym,'intraday'):regimeQuoteVersion(sym);return ['SPY','QQQ','IWM','XLK'].map(sym=>`${sym}:${part(sym)}`).concat(`VIX:${regimeQuoteVersion('VIX')}:${barVersion('VIX','daily')}`).join('~')}if(kind==='swing'){const part=sym=>closeArray(sym,'daily').length>=20?barVersion(sym,'daily'):regimeQuoteVersion(sym);return ['SPY','QQQ','IWM','XLK'].map(sym=>`${sym}:${part(sym)}`).concat(`VIX:${regimeQuoteVersion('VIX')}:${barVersion('VIX','daily')}`).join('~')}const part=sym=>closeArray(sym,'daily').length>=60?barVersion(sym,'daily'):regimeQuoteVersion(sym);return ['SPY','QQQ','IWM'].map(sym=>`${sym}:${part(sym)}`).concat(`TLT:${regimeQuoteVersion('TLT')}`,`VIX:${regimeQuoteVersion('VIX')}`).join('~')}
function analysisInputSignature(sym,kind){const cfg=deskCfg[kind],base=[analysisQuoteVersion(sym),barVersion(sym,cfg.bar),earningsVersion(sym),regimeInputSignature(kind),String(state?.settings?.earningsPenalty||10),new Date().toISOString().slice(0,10)];if(kind==='long')base.push(barVersion(sym,'daily'),fundamentalVersion(sym));return base.join('~')}
function resetDerivedCaches(){analysisCache.clear();regimeCache.clear()}
function performanceSnapshot(){const byKind={};for(const kind of ['day','swing','long']){const hits=perfMetrics.cacheHits[kind],misses=perfMetrics.cacheMisses[kind],total=hits+misses;byKind[kind]={entries:[...analysisCache.keys()].filter(k=>k.endsWith(`:${kind}`)).length,hits,misses,hitRate:total?Math.round(hits/total*100):0}}const f=runtime?.feed||{},masterUniverse=allSymbols().filter(s=>s!=='VIX'),specialAvailable=num(q('VIX').price)>0||Object.prototype.hasOwnProperty.call(runtime?.quotes||{},'VIX');return {masterSymbols:new Set(masterUniverse).size,specialIndexSymbols:specialAvailable?1:0,activeUniverse:allSymbols().length,finnhubSubscriptions:Array.isArray(f.subscribedSymbols)?f.subscribedSymbols.length:0,alpacaSubscriptions:Array.isArray(f.alpacaSubscribedSymbols)?f.alpacaSubscribedSymbols.length:0,analysis:byKind,quoteEvents:perfMetrics.quoteEvents,renderRequests:perfMetrics.renderRequests,renderExecuted:perfMetrics.renderExecuted,renderSkipped:perfMetrics.renderSkipped,fullRenders:perfMetrics.fullRenders,lastRenderMs:Math.round(perfMetrics.lastRenderMs*100)/100,averageRenderMs:perfMetrics.fullRenders?Math.round(perfMetrics.totalRenderMs/perfMetrics.fullRenders*100)/100:0}}
function avg(a){return a.length?a.reduce((x,y)=>x+y,0)/a.length:0}
function sma(a,n){return a.length>=n?avg(a.slice(-n)):0}
function ema(a,n){if(!a.length)return 0;const k=2/(n+1);let v=a[0];for(let i=1;i<a.length;i++)v=a[i]*k+v*(1-k);return v}
function rsi(a,n=14){if(a.length<n+1)return 50;let g=0,l=0;for(let i=a.length-n;i<a.length;i++){const d=a[i]-a[i-1];if(d>0)g+=d;else l-=d}if(l===0)return 100;const rs=(g/n)/(l/n);return 100-(100/(1+rs))}
function atr(bs,n=14){if(bs.length<n+1)return 0;const tr=[];for(let i=1;i<bs.length;i++)tr.push(Math.max(bs[i].h-bs[i].l,Math.abs(bs[i].h-bs[i-1].c),Math.abs(bs[i].l-bs[i-1].c)));return avg(tr.slice(-n))}
function ret(a,n){return a.length>n&&a[a.length-1-n]?((a.at(-1)/a[a.length-1-n])-1)*100:0}
function std(a,n=20){const x=a.slice(-n);if(x.length<3)return 0;const m=avg(x);return Math.sqrt(avg(x.map(v=>(v-m)**2)))}
function vwap(bs){const x=bs.slice(-26);let pv=0,v=0;x.forEach(b=>{const t=(b.h+b.l+b.c)/3;pv+=t*b.v;v+=b.v});return v?pv/v:0}
function marketOpenET(){const now=new Date(),parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(now);const o=Object.fromEntries(parts.map(x=>[x.type,x.value]));const mins=+o.hour*60 + +o.minute;return !['Sat','Sun'].includes(o.weekday)&&mins>=570&&mins<960}
function etDateKey(ms){if(!ms)return '';const p=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(ms));const o=Object.fromEntries(p.map(x=>[x.type,x.value]));return `${o.year}-${o.month}-${o.day}`}
function priceContext(sym){const x=q(sym),live=num(x.price),session=num(x.sessionClose),sessionAt=num(x.sessionCloseAt),fallback=num(x.previousClose)||num(x.priorSessionClose),close=session||fallback;let prev=session?(num(x.priorSessionClose)||num(x.previousClose)):num(x.priorSessionClose);if(prev&&close&&Math.abs(prev-close)<.000001)prev=0;const closeLabel=sessionAt&&etDateKey(sessionAt)===etDateKey(Date.now())?'TODAY CLOSE':'LAST CLOSE';return {live,today:close,close,prev,closeLabel,source:x.source||'cached',updated:num(x.updatedAt),providerUpdated:num(x.providerTimestamp),sessionAt}}
function marketSession(){return runtime?.feed?.marketSession||'closed'}
function quoteAgeMs(sym){const x=q(sym),stamp=num(x.providerTimestamp)||num(x.updatedAt);return stamp?Math.max(0,nowMs()-stamp):Infinity}
function isWebSocketQuote(sym){return String(q(sym).source||'').startsWith('finnhub-websocket')}
function isAlpacaSnapshot(sym){return String(q(sym).source||'').startsWith('alpaca-')&&String(q(sym).source||'').endsWith('-snapshot')}
