function numericGuidanceMarkup(e){if(!e)return '';const range=(lo,hi,currency=false)=>{if(lo==null&&hi==null)return '';const fmt=v=>currency?'$'+compactNumber(v):num(v).toFixed(2);if(lo!=null&&hi!=null)return `${fmt(lo)}–${fmt(hi)}`;return fmt(lo??hi)},revPrev=range(e.guidanceRevenuePrevLow,e.guidanceRevenuePrevHigh,true),revNew=range(e.guidanceRevenueNewLow,e.guidanceRevenueNewHigh,true),epsPrev=range(e.guidanceEpsPrevLow,e.guidanceEpsPrevHigh,false),epsNew=range(e.guidanceEpsNewLow,e.guidanceEpsNewHigh,false);if(!revNew&&!epsNew)return '';const rows=[];if(revNew)rows.push(`<div><small>Revenue guidance</small><b>${esc(revPrev?revPrev+' → '+revNew:revNew)}</b></div>`);if(epsNew)rows.push(`<div><small>EPS guidance</small><b>${esc(epsPrev?epsPrev+' → '+epsNew:epsNew)}</b></div>`);return `<div class="numeric-guidance">${rows.join('')}<small>Numeric guidance shown only from structured sourced evidence${e.guidanceSource?' · '+esc(e.guidanceSource):''}.</small></div>`}
function earningsIntelligenceCard(sym,kind='research'){const x=earningsIntelligence(sym),latest=x.latest,next=x.next,g=x.guidance;if(kind==='day'){if(!latest||dateAgeDays(latest.date)>3)return next&&daysUntilDate(next.date)===0?`<section class="card horizon-intel-card"><span class="eyebrow">Catalyst · Earnings</span><h3>Reports ${esc(String(next.hour||'TBD').toUpperCase())}</h3><p>EPS expected ${next.epsEstimate==null?'—':num(next.epsEstimate).toFixed(2)} · Revenue expected ${next.revenueEstimate==null?'—':'$'+compactNumber(next.revenueEstimate)}</p><button class="btn tiny ghost" data-research="${esc(sym)}" data-research-origin="day">Review Catalyst</button></section>`:'';const p=planFor(sym,'day'),sm=sessionMomentumContext(sym);return `<section class="card horizon-intel-card ${x.tone}"><span class="eyebrow">Catalyst · Earnings</span><h3>${esc(x.read)} · ${esc(titleCaseText(g.status))}</h3><div class="horizon-intel-grid"><span><small>EPS</small><b>${esc(earningsBeatLabel(latest.epsActual,latest.epsEstimate))}</b></span><span><small>Revenue</small><b>${esc(earningsBeatLabel(latest.revenueActual,latest.revenueEstimate))}</b></span><span><small>${esc(sm.sessionLabel)}</small><b>${esc(pctSigned(sm.sessionMove))}</b></span><span><small>RVOL</small><b>${num(p.rv).toFixed(2)}×</b></span></div><button class="btn tiny ghost" data-research="${esc(sym)}" data-research-origin="day">Review Earnings</button></section>`}if(kind==='swing'){if(!latest&&!next)return '';const reaction=latest?postEarningsReaction(sym,latest):null;return `<section class="card horizon-intel-card ${x.tone}"><span class="eyebrow">Earnings Context</span><h3>${latest?esc(x.read):'Upcoming'} · Guidance ${esc(titleCaseText(g.status))}</h3><p>${latest?`${esc(earningsBeatLabel(latest.epsActual,latest.epsEstimate))} · Revenue ${esc(earningsBeatLabel(latest.revenueActual,latest.revenueEstimate))}`:`${dateOnly(next.date)} · ${esc(String(next.hour||'TBD').toUpperCase())}`}</p>${reaction?`<div class="earnings-reaction"><small>Post-earnings reaction</small><b>${esc(reaction.label)}</b><span>${esc(reaction.detail)}</span></div>`:''}${numericGuidanceMarkup(latest)}<button class="btn tiny ghost" data-research="${esc(sym)}" data-research-origin="swing">Research</button></section>`}if(kind==='long'){const recent=x.events.filter(e=>e.epsActual!=null||e.revenueActual!=null).slice(0,4);return `<section class="card horizon-intel-card ${x.tone}"><span class="eyebrow">Earnings Trend</span><h3>${esc(x.read)} · Guidance ${esc(titleCaseText(g.status))}</h3><div class="earnings-trend-list">${recent.map(e=>`<div><b>${esc(`Q${e.quarter||'?'} ${e.year||''}`)}</b><span>EPS ${esc(earningsBeatLabel(e.epsActual,e.epsEstimate))}</span><span>Rev ${esc(earningsBeatLabel(e.revenueActual,e.revenueEstimate))}</span></div>`).join('')||'<div class="empty">No reported earnings history in the current cache.</div>'}</div>${numericGuidanceMarkup(latest)}<button class="btn tiny ghost" data-research="${esc(sym)}" data-research-origin="long">Full Earnings Research</button></section>`}return `<section class="card earnings-intelligence-card ${x.tone}"><div class="card-head"><div><span class="eyebrow">Earnings Intelligence</span><h2>${esc(sym)} · ${esc(x.read)}</h2><p>${latest?`${dateOnly(latest.date)} reported`:(next?`${dateOnly(next.date)} upcoming`:'No scheduled event')}</p></div><span class="score-pill ${x.tone}">${esc(titleCaseText(g.status))}</span></div>${latest?`<div class="earnings-intel-grid"><div><small>EPS</small><b>${esc(earningsBeatLabel(latest.epsActual,latest.epsEstimate))}</b><span>${latest.epsEstimate==null?'—':`Expected ${num(latest.epsEstimate).toFixed(2)} · Actual ${latest.epsActual==null?'—':num(latest.epsActual).toFixed(2)}`}</span></div><div><small>Revenue</small><b>${esc(earningsBeatLabel(latest.revenueActual,latest.revenueEstimate))}</b><span>${latest.revenueEstimate==null?'—':`Expected $${compactNumber(latest.revenueEstimate)} · Actual ${latest.revenueActual==null?'—':'$'+compactNumber(latest.revenueActual)}`}</span></div><div><small>Guidance</small><b>${esc(titleCaseText(g.status))}</b><span>${g.evidence?`${esc(g.evidence.source)} · ${esc(dateOnly(g.evidence.date))}`:'No explicit guidance evidence found'}</span></div></div>${numericGuidanceMarkup(latest)}`:''}${next?`<div class="earnings-next"><small>Next expectation</small><b>${dateOnly(next.date)} · ${esc(String(next.hour||'TBD').toUpperCase())}</b><span>EPS ${next.epsEstimate==null?'—':num(next.epsEstimate).toFixed(2)} · Revenue ${next.revenueEstimate==null?'—':'$'+compactNumber(next.revenueEstimate)}</span></div>`:''}<p class="research-footnote">Guidance is shown only when explicit raised/maintained/lowered/withdrawn language is found in mapped company news or SEC evidence. Otherwise it remains Not Provided.</p></section>`}
function secHorizonContext(sym,kind){const filings=researchFilingsFor(sym),days=kind==='day'?2:kind==='swing'?14:120,recent=filings.filter(f=>dateAgeDays(f.filedAt)<=days),material=recent.filter(f=>['material','offering','insider','ownership'].includes(String(f.category||'').toLowerCase())),x=runtime?.secIntelligence?.[sym];return {filings,recent,material,intelligence:x,risk:x?.offeringRisk||'Low'}}
function secHorizonCard(sym,kind){const x=secHorizonContext(sym,kind);if(kind==='day'){const f=x.material[0];if(!f)return '';return `<section class="card horizon-intel-card warning"><span class="eyebrow">Catalyst · SEC Filing</span><h3>${esc(secFilingMeaning(f))}</h3><p>${esc(f.form)} · ${dateOnly(f.filedAt)} · ${esc(f.description||f.meaning||'Material filing')}</p><button class="btn tiny ghost" data-research="${esc(sym)}" data-research-origin="day">Review Catalyst</button></section>`}if(kind==='swing'){const f=x.material[0];const status=f?'MATERIAL UPDATE':'CLEAR';return `<section class="card horizon-intel-card ${f?'warning':'positive'}"><span class="eyebrow">Filing / Catalyst Risk</span><h3>${status}</h3><p>${f?`${esc(secFilingMeaning(f))} · ${dateOnly(f.filedAt)}`:'No material recent SEC filing in the swing window.'}</p><button class="btn tiny ghost" data-research="${esc(sym)}" data-research-origin="swing">Review Filings</button></section>`}return secIntelligenceSummary(sym)}
function aiEvidenceFingerprint(sym,horizon='research'){const lu=runtime?.lastUpdated||{},parts=[String(sym||'').toUpperCase(),horizon,analysisInputSignature(sym,'day'),analysisInputSignature(sym,'swing'),analysisInputSignature(sym,'long'),lu.news||0,lu.earnings||0,lu.filings||0,lu.fundamentals||0];return parts.join('|')}
function aiResultKey(sym,horizon='research',reviewType='ticker',question=''){const q=reviewType==='custom'?String(question||'').trim().toLowerCase().slice(0,240):'';return `${String(sym||'').toUpperCase()}|${horizon}|${reviewType}|${q}|${aiEvidenceFingerprint(sym,horizon)}`}
function latestAIResultFor(sym){const target=String(sym||'').toUpperCase(),items=Object.values(aiResearchResults).filter(r=>r&&r._symbol===target).sort((a,b)=>num(b._generatedAt)-num(a._generatedAt));return items[0]||null}
function researchFilings(sym){const filings=researchFilingsFor(sym);return `<div class="research-section-stack"><section class="card"><div class="card-head"><div><span class="eyebrow">SEC Filings</span><h2>${esc(sym)} filings & ownership context</h2><p>Friendly filing names first; SEC form codes remain secondary reference.</p></div><div class="button-row"><span class="count-pill">${filings.length}</span><button class="btn small ghost" data-jump="filings">All Filings</button></div></div>${secIntelligenceSummary(sym)}<div class="research-filings-list">${filings.slice(0,12).map(f=>`<article><div><b>${esc(secFilingMeaning(f))}</b><span>${esc(f.form)} · ${dateOnly(f.filedAt)}</span></div><p>${esc(f.description||f.meaning||secFormMeaning(f.form))}</p>${secFilingDetail(f)?`<small class="sec-transaction-detail">${esc(secFilingDetail(f))}</small>`:''}${f.url?`<button class="btn small ghost" data-url="${esc(f.url)}">Open Filing</button>`:''}</article>`).join('')||`<div class="empty">No mapped SEC filings for ${esc(sym)}.</div>`}</div></section></div>`}
function researchFilingsFor(sym){const target=String(sym||'').toUpperCase();return (runtime?.filings||[]).filter(x=>String(x.symbol||'').toUpperCase()===target).sort((a,b)=>String(b.filedAt||'').localeCompare(String(a.filedAt||'')))}
function horizonCard(sym,kind){const label=kind==='day'?'Day Trade':kind==='swing'?'Swing':'Long-Term';if(!canonicalResearchReady(sym))return `<article class="research-horizon-card warning"><div><span class="eyebrow">${label}</span><h3>Needs hydration</h3><p>Stage the candidate before desk-grade analysis.</p></div></article>`;const p=planFor(sym,kind),reg=marketRegimeFor(kind),ready=tradeReadiness(sym,kind);return `<article class="research-horizon-card ${p.tone}"><div><span class="eyebrow">${label}</span><h3>${Math.round(p.score)} / 100 · ${titleCaseText(actionState(p))}</h3><p>${regimeDisplayLabel(reg.label)} market · ${titleCaseText(p.eventRisk)} event risk</p><div class="research-readiness-line"><small>Trade Readiness</small><b>${esc(ready.status)}</b></div></div><button class="btn small ghost" data-research-desk="${kind}:${esc(sym)}">Open ${label}</button></article>`}
function researchSummary(sym){const target=String(sym||'').toUpperCase(),scanner=scannerResultFor(target),earn=earningsInfo(target),ds=quoteState(target);if(!canonicalResearchReady(target))return scanner?`${target} is ranked ${Math.round(num(scanner.score))}/100 in ${scannerModeTitle(scanner.mode||discoveryMode)} Discovery. Stage it for full desk analysis.`:`${target} needs canonical market data before full research is available.`;const plans=['day','swing','long'].map(k=>planFor(target,k)),best=[...plans].sort((a,b)=>b.score-a.score)[0],label=best.kind==='day'?'Day Trade':best.kind==='swing'?'Swing':'Long-Term',earnText=earn.days===null?'no scheduled earnings date':`earnings in ${earn.days} day${earn.days===1?'':'s'}`;return `${label} is currently the strongest deterministic desk fit at ${Math.round(best.score)}/100. ${earnText}. Data: ${ds.label}.`}
function researchConfirmationCard(sym){const r=latestAIResultFor(sym);if(!r)return `<section class="card research-confirmation empty-confirmation"><div><span class="eyebrow">Research Confirmation</span><h3>AI review not run</h3><p>Optional second opinion. It never changes the deterministic desk Action/Score.</p></div><button class="btn" data-research-ai="${esc(sym)}" data-ai-origin="research">Ask AI</button></section>`;const horizonLabel=r.bestFitHorizon==='day'?'Day Trade':r.bestFitHorizon==='swing'?'Swing':r.bestFitHorizon==='long'?'Long-Term':'No horizon';return `<section class="card research-confirmation ${String(r.verdict||'informational').toLowerCase()}"><div class="research-confirmation-head"><div><span class="eyebrow">Research Confirmation</span><h3>${esc(titleCaseText(r.verdict||'Informational'))}</h3><p>${esc(r.summary||r.nextAction||'AI review completed.')}</p></div><div class="research-confidence"><small>Confidence</small><b>${Math.round(num(r.confidence))}%</b></div></div><div class="research-confirmation-grid"><div><small>Best-fit horizon</small><b>${esc(horizonLabel)}</b></div><div><small>Key reasons</small><b>${esc((r.reasons||[]).slice(0,3).join(' · ')||'—')}</b></div><div><small>Risks</small><b>${esc((r.risks||[]).slice(0,2).join(' · ')||'None identified')}</b></div><div><small>Catalyst</small><b>${esc(r.catalyst||'None identified')}</b></div></div><div class="button-row"><button class="btn ghost" data-research-ai="${esc(sym)}" data-ai-origin="research">Ask Again</button>${['day','swing','long'].includes(r.bestFitHorizon)?`<button class="btn primary" data-research-desk="${r.bestFitHorizon}:${esc(sym)}">Open ${esc(horizonLabel)}</button>`:''}</div><p class="research-footnote">AI confirmation is advisory context only. It cannot place trades or alter Action/Score.</p></section>`}
