 const qq=q(sym),ds=quoteState(sym),pc=priceContext(sym),scanner=scannerResultFor(sym),news=newsForSymbol(sym),filings=researchFilingsFor(sym),earn=earningsInfo(sym),ready=canonicalResearchReady(sym);
 const snapshot=`<section class="card research-snapshot"><div class="research-symbol-line"><div><span class="eyebrow">Research Decision Snapshot</span><h2>${esc(sym)}</h2><p>${esc(researchSummary(sym))}</p></div><div class="research-price"><strong>${num(pc.live||qq.price)?`$${money(pc.live||qq.price)}`:'—'}</strong><span class="${num(qq.changePercent)>=0?'positive':'negative'}">${num(qq.price)?pct(qq.changePercent):'No live quote'}</span><small>${esc(ds.label)} · ${esc(ds.detail||'')}</small></div></div><div class="research-fact-strip"><div><small>Next Earnings</small><b>${earn.days===null?'Not scheduled':`${earn.days} day${earn.days===1?'':'s'}`}</b></div><div><small>Catalysts</small><b>${news.length} news item${news.length===1?'':'s'}</b></div><div><small>SEC</small><b>${filings.length} filing${filings.length===1?'':'s'}</b></div><div><small>Discovery Rank</small><b>${scanner?`${Math.round(num(scanner.score))}/100`:'—'}</b></div></div></section>`;
