 return `<div class="research-overview-grid">${snapshot}${takeaway}<section class="research-horizon-grid">${horizonCard(sym,'day')}${horizonCard(sym,'swing')}${horizonCard(sym,'long')}</section><section class="research-evidence-heading"><span class="eyebrow">Key Sourced Evidence & Risk</span><h2>Validate the idea before the AI second opinion</h2></section><div class="research-evidence-grid">${earningsIntelligenceCard(sym,'research')}${secIntelligenceSummary(sym)}${providerIntelligenceCard(sym)}${cross}</div>${researchConfirmationCard(sym)}</div>`
