function renderResearch(){
 const symbols=allResearchSymbols();if(!researchSymbol)researchSymbol=symbols[0]||state?.ui?.selectedTicker||'SPY';const tabs=[['overview','Overview'],['fundamentals','Fundamentals'],['catalysts','Catalysts'],['filings','Filings']],body=researchTab==='fundamentals'?researchFundamentals(researchSymbol):researchTab==='catalysts'?researchCatalysts(researchSymbol):researchTab==='filings'?researchFilings(researchSymbol):researchOverview(researchSymbol),originLabel=researchOrigin==='day'?'Day Trade':researchOrigin==='swing'?'Swing':researchOrigin==='long'?'Long-Term':researchOrigin==='discovery'?'Discovery':researchOrigin==='ai'?'AI Copilot':'Dashboard';
 return `<div class="page research-page" data-scope-marker="research-context-v1421">${pageHead('Research','Deep evidence for one symbol. Trading decisions remain in the horizon-specific desks.','fundamentals','','none')}<section class="card research-command"><div class="research-command-symbol"><span class="eyebrow">Research Target</span><div class="research-target-paths"><label><small>Choose from List</small><select data-research-symbol aria-label="Choose research symbol from list">${symbols.map(s=>`<option value="${esc(s)}" ${s===researchSymbol?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label><small>Add Symbol</small><span class="research-add-symbol"><input data-research-symbol-input placeholder="Ticker" maxlength="8" aria-label="Enter any ticker"><button class="btn tiny" data-research-load>Load</button></span></label><span class="data-badge ${quoteState(researchSymbol).tone}">${statusDot(quoteState(researchSymbol).light,quoteState(researchSymbol).label)}${esc(quoteState(researchSymbol).label)}</span></div><p>Opened from ${esc(originLabel)} · symbol context is preserved when you return.</p></div><div class="research-desk-actions"><button class="btn ghost" data-research-back>Back to ${esc(originLabel)}</button><button class="btn" data-research-ai="${esc(researchSymbol)}" data-ai-origin="research">Ask AI</button></div></section><nav class="research-tabs" aria-label="Research views">${tabs.map(([k,l])=>`<button class="${researchTab===k?'active':''}" data-research-tab="${k}">${l}</button>`).join('')}</nav>${body}</div>`
}
function openResearch(sym,origin=page){researchSymbol=String(sym||state?.ui?.selectedTicker||'SPY').toUpperCase();researchOrigin=origin||page;researchTab='overview';api('/api/ui/ticker',{symbol:researchSymbol}).catch(()=>{});setPage('research')}

function dataLight(data){const label=String(data?.label||'');if(label.includes('LIVE')||label==='CURRENT'||label==='INDICATIVE')return 'green';if(label==='CACHED'||label==='CURRENT'||label==='STALE'||label==='SNAPSHOT'||label==='DEGRADED'||label==='Demo')return 'yellow';return 'red'}
function setupLight(p){const action=actionState(p);if(action==='INVALIDATED'||p.eventRisk==='HIGH'||p.score<45)return 'red';if(p.score>=60&&p.eventRisk==='LOW'&&dataLight(p.data)!=='red')return 'green';return 'yellow'}

function statusDot(tone,label){return `<span class="status-dot ${tone}" title="${esc(label)}" aria-label="${esc(label)}"></span>`}
function rangeText(a){return a&&a.every(Number.isFinite)?`$${money(a[0])} – $${money(a[1])}`:'Waiting for bars'}
function timePair(ms){if(!ms)return 'No successful pull yet';const d=new Date(ms);return `ET ${d.toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',second:'2-digit'})} · PT ${d.toLocaleString('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',second:'2-digit'})}`}
function maintenanceTimePair(ms){if(!ms)return 'Not run yet';const d=new Date(ms),date=d.toLocaleDateString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric'}),et=d.toLocaleTimeString('en-US',{timeZone:'America/New_York',hour:'numeric',minute:'2-digit'}),pt=d.toLocaleTimeString('en-US',{timeZone:'America/Los_Angeles',hour:'numeric',minute:'2-digit'});return `${date} · ${et} ET / ${pt} PT`}
function freshness(topic='quotes'){const feed=runtime?.feed||{},topicTime=runtime?.lastUpdated?.[topic]||runtime?.lastUpdated?.cache,lastTrade=num(feed.lastTradeAt),lastAlpaca=num(feed.lastAlpacaAt),lastAlpacaStream=num(feed.lastAlpacaStreamAt),state=feed.feedState||runtime?.status||'stopped',session=feed.marketSession||'closed';let label=sessionLabel(session);if(topic==='quotes'){if(state==='streaming'||state==='alpaca-streaming'||state==='overnight-streaming')label=liveLabelForSession(session);else if(state==='snapshot-live')label='SNAPSHOT';else if(state==='reconnecting')label='RECONNECTING';else if(runtime?.status==='stopped')label='STOPPED'}const stamp=topic==='quotes'?(Math.max(lastTrade,lastAlpaca,lastAlpacaStream)||topicTime):topicTime;return `<div class="page-freshness"><b class="${label.includes('LIVE')?'positive':label==='RECONNECTING'?'warning':'muted'}">${label}</b><span>${topic==='quotes'?'Last market update':'Last update'}: ${timePair(stamp)}</span></div>`}
function pageHead(title,sub,topic='quotes',actions='',regimeKind='common'){
 const m=regimeKind==='none'?null:(['day','swing','long'].includes(regimeKind)?marketRegimeFor(regimeKind):marketRegime()),light=m?(m.tone==='bullish'?'green':m.tone==='bearish'?'red':'yellow'):'yellow',regimeTitle=['day','swing','long'].includes(regimeKind)?deskRegimeName(regimeKind):'Market Regime',fresh=topic==='none'?'':freshness(topic);
 return `<header class="page-head ${m?'':'no-regime'}"><div class="page-head-copy"><h1>${esc(title)}</h1><p>${brandInline(sub)}</p></div><div class="page-head-status-group">${m?`<div class="page-head-sentiment">${statusDot(light,`${regimeDisplayLabel(m.label)} ${regimeTitle}`)}<span><small>${regimeTitle}</small><b>${regimeDisplayLabel(m.label)}</b></span></div>`:''}<div class="page-tools">${actions}${fresh}</div></div></header>`
}
function quoteCard(sym){const p=priceContext(sym),c=q(sym),ds=quoteState(sym);return `<section class="card market-quote"><div class="market-quote-layout"><div class="market-quote-primary"><div class="market-quote-name"><h3>${sym}</h3><small>${esc(MARKET_ROLES[sym]||'Market context')}</small></div><small class="price-kicker">${p.live?'Last Price':'Latest Price'}</small><div class="market-price">$${money(p.live||p.close||p.prev)}</div></div><div class="market-quote-side"><div class="market-quote-status-row"><span class="data-badge ${ds.tone}">${statusDot(ds.light,`${ds.label} ${sym} quote`)}${ds.label}</span></div><div class="market-quote-change-row ${c.changePercent>=0?'positive':'negative'}">${pct(c.changePercent)}</div><div class="market-quote-stat"><small>${p.closeLabel}</small><b>${p.close?`$${money(p.close)}`:'—'}</b></div><div class="market-quote-stat"><small>Previous Close</small><b>${p.prev?`$${money(p.prev)}`:'—'}</b></div></div></div></section>`}
function vixCard(){const v=vixContext(),ds=quoteState('VIX');return `<section class="card market-quote vix-card"><div class="market-quote-layout"><div class="market-quote-primary"><div class="market-quote-name"><h3>VIX</h3><small>30-day volatility pressure</small></div><small class="price-kicker">Last Value</small><div class="market-price">${v.available?money(v.price):'—'}</div><div class="vix-state ${v.tone}">${v.stateLabel}</div></div><div class="market-quote-side"><div class="market-quote-status-row"><span class="data-badge ${ds.tone}">${statusDot(ds.light,`${ds.label} VIX quote`)}${ds.label}</span></div><div class="market-quote-change-row ${v.change>=0?'negative':'positive'}">${v.available?pct(v.change):'Unavailable'}</div><div class="market-quote-stat"><small>Previous Close</small><b>${v.previous?money(v.previous):'—'}</b></div><div class="market-quote-stat"><small>5-Day</small><b>${v.fiveDay===null?'—':pct(v.fiveDay)}</b></div><div class="market-quote-stat optional-stat"><small>20-Day Avg</small><b>${v.avg20?money(v.avg20):'—'}</b></div></div></div></section>`}
function marketMiniCard(sym){const quote=q(sym),price=num(quote.price),change=num(quote.changePercent);return `<div class="market-mini"><div><b>${sym}</b><small>${esc(MARKET_ROLES[sym]||'Context')}</small></div><div class="market-mini-value"><strong>${price?`$${money(price)}`:'—'}</strong><span class="${change>=0?'positive':'negative'}">${price?pct(change):'No Data'}</span></div></div>`}
function driverGroup(title,items,tone){return `<div class="driver-group ${tone}"><b>${title}</b>${items.length?items.map(x=>`<span>• ${esc(x)}</span>`).join(''):'<span>• No strong driver</span>'}</div>`}
function marketRegimeBar(m){const score=Math.max(0,Math.min(100,m.sentimentScore));return `<div class="regime-meter-wrap"><div class="regime-meter" role="meter" aria-label="Market regime score" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${score}"><span class="regime-marker" style="--score:${score}%"><i></i><b>${score}</b></span></div><div class="regime-scale"><span>Risk-Off</span><span>Cautious</span><span>Mixed</span><span>Constructive</span><span>Risk-On</span></div></div>`}

function marketContext(){const m=marketRegime();return `<section class="market-stack compact-market-stack"><section class="card regime-panel compact-regime-panel"><div class="regime-panel-head"><div class="regime-panel-copy"><span class="eyebrow">Market Regime · Cross-Module</span><div class="regime-heading regime-heading-with-market"><div class="regime-heading-primary"><h2>${regimeDisplayLabel(m.label)}</h2><span class="regime-score-inline ${m.tone==='bullish'?'positive':m.tone==='bearish'?'negative':'warning'}">${m.sentimentScore} / 100</span></div><div class="regime-live-strip">${regimeQuotePill('SPY')}${regimeQuotePill('QQQ')}${regimeDirectionalPill(m)}<span class="data-confidence">Data Confidence ${m.confidence}%</span></div></div><p>Equities + volatility + rates + global drivers${broadOptionsRegimeComponent()!=null?' + broad-market options':''}. Global context is correlated here, then interpreted by horizon.</p></div></div>${marketRegimeBar(m)}${horizonLensMarkup()}<div class="regime-drivers compact">${driverGroup('Positive',m.positive,'positive')}${driverGroup('Negative',m.negative,'negative')}${driverGroup('Context',m.context,'context')}</div></section></section>`}

function topPlans(kind,n=3){return deskWL(kind).symbols.map(s=>planFor(s,kind)).sort((a,b)=>b.score-a.score).slice(0,n)}




function deskActions(kind){const enabled=deskEnabled(kind);return `<div class="desk-head-actions"><button class="engine-switch ${enabled?'on':'off'}" data-engine-toggle="${kind}" aria-pressed="${enabled}"><span>${enabled?'Engine On':'Engine Off'}</span><i></i></button><div class="field compact desk-sort-field"><label for="sort-${kind}">Sort By</label><select id="sort-${kind}" data-sort="${kind}" ${enabled?'':'disabled'}><option value="quality" ${sortState[kind]==='quality'?'selected':''}>Setup Quality</option><option value="ticker" ${sortState[kind]==='ticker'?'selected':''}>Ticker</option><option value="change" ${sortState[kind]==='change'?'selected':''}>Daily Change</option><option value="entry" ${sortState[kind]==='entry'?'selected':''}>Distance to Entry</option></select></div></div>`}
function deskRegimeControlGrid(kind){return `<div class="desk-regime-control-grid"><div class="desk-regime-slot">${deskRegimeStrip(kind)}</div><div class="desk-control-panel" aria-label="${deskCfg[kind].title} controls"><div><span class="eyebrow">Desk Controls</span><p>Engine and ranking controls.</p></div>${deskActions(kind)}</div></div>`}
function actionState(p){if(!p.price)return 'WAITING';if(p.eventRisk==='HIGH')return 'EVENT RISK';if(p.price>=p.entry[0]&&p.price<=p.entry[1])return 'IN ENTRY ZONE';if(p.price<p.invalid)return 'INVALIDATED';if(p.price>p.target[0])return 'TRIM / REVIEW';if(p.price>p.entry[1])return 'EXTENDED';return 'APPROACHING ENTRY'}
function deskRow(p,kind){const pc=priceContext(p.sym),c=q(p.sym),light=setupLight(p),dLight=dataLight(p.data),ds=quoteState(p.sym);return `<div class="desk-row ${selected[kind]===p.sym?'selected':''}" data-select="${kind}:${p.sym}"><div class="desk-cell cell-symbol" data-label="Symbol / Price"><div class="symbol-line">${statusDot(light,`${p.sym} setup ${light}`)}<strong>${p.sym}</strong><span class="data-badge ${p.data.tone}" title="${esc(ds.detail||'')}">${statusDot(dLight,`${p.data.label} data`)}${p.data.label}</span></div><div class="row-price-line"><strong class="symbol-price">$${money(pc.live||p.price)}</strong><span class="${c.changePercent>=0?'positive':'negative'}">${pct(c.changePercent)}</span></div>${marketSession()==='overnight'&&num(c.bid)&&num(c.ask)?`<small class="desk-close-line"><span>Bid / Ask</span><b>$${money(c.bid)} / $${money(c.ask)}</b></small>`:''}<small class="desk-close-line"><span>${pc.closeLabel}</span><b>$${money(pc.close)}</b></small><small class="desk-close-line"><span>Previous Close</span><b>$${money(pc.prev)}</b></small></div><div class="desk-cell cell-action" data-label="Action / Score"><span class="score-pill ${p.tone}">${titleCaseText(p.direction)}</span><strong class="score-number">${Math.round(p.score)} / 100</strong><small>${titleCaseText(actionState(p))}</small></div><div class="desk-cell zone-entry cell-entry" data-label="Entry Zone"><strong>${rangeText(p.entry)}</strong><small>Entry Zone</small></div><div class="desk-cell zone-target cell-target" data-label="Trim / Target"><strong>${rangeText(p.target)}</strong><small>Trim / Target Zone</small></div><div class="desk-cell zone-invalid cell-invalid" data-label="Invalidation"><strong>$${money(p.invalid)}</strong><small>Invalidation · ${p.rr.toFixed(1)}R</small></div><div class="desk-cell cell-context" data-label="Quality / Context"><strong>${p.rs>=0?'+':''}${p.rs.toFixed(1)} RS</strong><small>RVOL ${p.rv.toFixed(2)}× · Event ${titleCaseText(p.eventRisk)}<br>Data confidence ${titleCaseText(p.quality)}<br>Readiness ${esc(tradeReadiness(p.sym,kind).status)}</small></div></div>`}
function sortPlans(plans,kind){const mode=sortState[kind];return plans.sort((a,b)=>mode==='ticker'?a.sym.localeCompare(b.sym):mode==='change'?num(q(b.sym).changePercent)-num(q(a.sym).changePercent):mode==='entry'?Math.abs(a.price-a.entry[1])-Math.abs(b.price-b.entry[1]):b.score-a.score)}
function chartSVG(p){const bs=p.bars.slice(-90);if(bs.length<3)return '<div class="empty">Historical bars are required for the chart.</div>';const W=1000,H=330,pad={l:45,r:190,t:22,b:28};const values=bs.flatMap(b=>[b.h,b.l,p.entry[0],p.entry[1],p.target[0],p.target[1],p.invalid]).filter(Number.isFinite);let min=Math.min(...values),max=Math.max(...values),span=max-min||1;min-=span*.08;max+=span*.08;const x=i=>pad.l+i*(W-pad.l-pad.r)/(bs.length-1),y=v=>pad.t+(max-v)*(H-pad.t-pad.b)/(max-min),labelX=W-12;const line=bs.map((b,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(b.c).toFixed(1)}`).join(' ');const zone=(a,color,label)=>`<rect x="${pad.l}" y="${y(a[1])}" width="${W-pad.l-pad.r}" height="${Math.max(2,y(a[0])-y(a[1]))}" fill="${color}" opacity=".11"/><text class="plan-chart-label" x="${labelX}" y="${(y(a[0])+y(a[1]))/2+3}" fill="${color}" text-anchor="end">${label}</text>`;const invalid=`<line x1="${pad.l}" y1="${y(p.invalid)}" x2="${W-pad.r}" y2="${y(p.invalid)}" stroke="#ff6678" stroke-dasharray="6 5"/><text class="plan-chart-label" x="${labelX}" y="${y(p.invalid)+3}" fill="#ff6678" text-anchor="end">Invalidation · $${money(p.invalid)}</text>`;const grid=[0,.25,.5,.75,1].map(t=>{const v=min+(max-min)*t;return `<line x1="${pad.l}" y1="${y(v)}" x2="${W-pad.r}" y2="${y(v)}" stroke="#172638"/><text x="4" y="${y(v)+3}" fill="#71849a" font-size="9">${money(v)}</text>`}).join('');return `<svg class="plan-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${p.sym} price chart with entry, target, and invalidation overlays">${grid}${zone(p.entry,'#2fe0a8',`Entry · $${money(p.entry[0])}–$${money(p.entry[1])}`)}${zone(p.target,'#21c8f3',`Target · $${money(p.target[0])}–$${money(p.target[1])}`)}${invalid}<path d="${line}" fill="none" stroke="#edf5ff" stroke-width="2"/><circle cx="${x(bs.length-1)}" cy="${y(bs.at(-1).c)}" r="4" fill="#f4bc62"/></svg><div class="chart-legend"><span><i class="legend-dot" style="background:#2fe0a8"></i>Entry Zone</span><span><i class="legend-dot" style="background:#21c8f3"></i>Trim / Target</span><span><i class="legend-dot" style="background:#ff6678"></i>Invalidation</span></div>`}
function fundamentals(p){const f=runtime?.fundamentals?.[p.sym]||{};const items=[['Revenue Growth',f.revenueGrowth?`${num(f.revenueGrowth).toFixed(1)}%`:'—'],['EPS Growth',f.epsGrowth?`${num(f.epsGrowth).toFixed(1)}%`:'—'],['P/E',f.peRatio?num(f.peRatio).toFixed(1):'—'],['Forward P/E',f.forwardPeRatio?num(f.forwardPeRatio).toFixed(1):'—'],['P/S',f.psRatio?num(f.psRatio).toFixed(1):'—'],['Gross Margin',f.grossMargin?`${num(f.grossMargin).toFixed(1)}%`:'—'],['Operating Margin',f.operatingMargin?`${num(f.operatingMargin).toFixed(1)}%`:'—'],['Net Margin',f.netMargin?`${num(f.netMargin).toFixed(1)}%`:'—'],['ROE',f.roe?`${num(f.roe).toFixed(1)}%`:'—'],['Debt / Equity',f.debtToEquity?num(f.debtToEquity).toFixed(1):'—'],['Current Ratio',f.currentRatio?num(f.currentRatio).toFixed(2):'—']];return `<div class="fund-grid">${items.map(x=>`<div class="fund"><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div>`}
function compactNumber(v){v=num(v);if(!v)return '—';const a=Math.abs(v);if(a>=1e12)return `${(v/1e12).toFixed(2)}T`;if(a>=1e9)return `${(v/1e9).toFixed(2)}B`;if(a>=1e6)return `${(v/1e6).toFixed(1)}M`;if(a>=1e3)return `${(v/1e3).toFixed(1)}K`;return v.toFixed(0)}
function marketCapText(v){v=num(v);if(!v)return '—';return '$'+compactNumber(v<1e9?v*1e6:v)}
function nextEarningsForSymbol(sym){const now=new Date().toISOString().slice(0,10);return (runtime?.earnings||[]).filter(e=>String(e.symbol||'').toUpperCase()===String(sym||'').toUpperCase()&&String(e.date||'')>=now).sort((a,b)=>String(a.date).localeCompare(String(b.date)))[0]}
function stockKeyStatistics(p,kind){
 const c=q(p.sym),f=runtime?.fundamentals?.[p.sym]||{},daily=bars(p.sym,'daily'),avgVol=avg(daily.slice(-20).map(b=>num(b.v)).filter(Boolean)),earn=nextEarningsForSymbol(p.sym),high52=num(f.fiftyTwoWeekHigh),low52=num(f.fiftyTwoWeekLow),spread=num(c.ask)&&num(c.bid)?num(c.ask)-num(c.bid):0,spreadPct=spread&&p.price?spread/p.price*100:0;
 const all={MarketCap:marketCapText(f.marketCap),PE:num(f.peRatio)?num(f.peRatio).toFixed(1):'—',ForwardPE:num(f.forwardPeRatio)?num(f.forwardPeRatio).toFixed(1):'—',High52:high52?`$${money(high52)}`:'—',Low52:low52?`$${money(low52)}`:'—',DayHigh:num(c.high)?`$${money(c.high)}`:'—',DayLow:num(c.low)?`$${money(c.low)}`:'—',Open:num(c.open)?`$${money(c.open)}`:'—',Prev:num(c.previousClose||c.priorSessionClose)?`$${money(c.previousClose||c.priorSessionClose)}`:'—',Volume:num(c.volume)?compactNumber(c.volume):'—',AvgVol:avgVol?compactNumber(avgVol):'—',BidAsk:num(c.bid)&&num(c.ask)?`$${money(c.bid)} / $${money(c.ask)}`:'—',Spread:spread?`${spreadPct.toFixed(2)}%`:'—',Earnings:earn?`${dateOnly(earn.date)} · ${esc(earn.hour||'TBD')}`:'—',ROE:num(f.roe)?`${num(f.roe).toFixed(1)}%`:'—',Current:num(f.currentRatio)?num(f.currentRatio).toFixed(2):'—',Dividend:num(f.dividendYield)?`${num(f.dividendYield).toFixed(2)}%`:'—'};
 const items=kind==='day'?[['Day High',all.DayHigh],['Day Low',all.DayLow],['Open',all.Open],['Previous Close',all.Prev],['Volume',all.Volume],['20D Avg Volume',all.AvgVol],['Bid / Ask',all.BidAsk],['Spread',all.Spread],['Next Earnings',all.Earnings]]:kind==='swing'?[['52W High',all.High52],['52W Low',all.Low52],['20D Avg Volume',all.AvgVol],['Next Earnings',all.Earnings],['Market Cap',all.MarketCap]]:[['Market Cap',all.MarketCap],['52W High',all.High52],['52W Low',all.Low52],['ROE',all.ROE],['Current Ratio',all.Current],['Dividend Yield',all.Dividend],['Next Earnings',all.Earnings]];
 return `<section class="stock-stats stock-stats-visible"><div class="stock-stats-head"><div><span class="eyebrow">Supporting Statistics</span><h3>${esc(p.sym)} supporting evidence</h3></div><span class="data-badge ${quoteState(p.sym).tone}">${quoteState(p.sym).label}</span></div><div class="stock-stats-grid">${items.map(([k,v])=>`<div class="stock-stat"><small>${esc(k)}</small><strong>${v}</strong></div>`).join('')}</div></section>`
}
function newsForSymbol(sym){const target=String(sym||'').toUpperCase();return (runtime?.news||[]).filter(n=>{const symbols=(n.symbols||[]).map(x=>String(x).toUpperCase()),related=String(n.related||'').toUpperCase().split(/[,;\s]+/).filter(Boolean);return symbols.includes(target)||related.includes(target)}).sort((a,b)=>num(b.datetime)-num(a.datetime))}
function tickerNewsPanel(sym){const items=newsForSymbol(sym).slice(0,6);return `<section class="card ticker-news-panel"><div class="card-head"><div><span class="eyebrow">Ticker News</span><h3>${esc(sym)} News & Catalysts</h3><p>Recent company-specific headlines.</p></div><span class="count-pill">${items.length} recent</span></div><div class="ticker-news-grid">${items.map(n=>`<article class="ticker-news-item"><div class="meta"><span>${esc(n.source||'News')}</span><span>${n.datetime?new Date(num(n.datetime)*1000).toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'Time unavailable'}</span></div><h4>${esc(n.headline)}</h4><p>${esc(n.summary||'No summary available.')}</p>${n.url?`<button class="btn small ghost" data-url="${esc(n.url)}">Open Source</button>`:''}</article>`).join('')||`<div class="empty">No recent news for ${esc(sym)}.</div>`}</div></section>`}
function detailCard(p,kind){
 const pc=priceContext(p.sym),c=q(p.sym),ds=quoteState(p.sym),regime=marketRegimeFor(kind),tickerNews=newsForSymbol(p.sym),earn=earningsIntelligenceCard(p.sym,kind),sec=secHorizonCard(p.sym,kind);
 const eventContext=`<section class="card event-data-context-card"><div class="card-head event-data-context-head"><div><h3>Event & Data Context</h3></div><div class="button-row event-context-actions"><button class="btn tiny" data-research-ai="${p.sym}" data-ai-origin="${kind}">Ask AI</button><button class="btn tiny ghost" data-research="${p.sym}" data-research-origin="${kind}">Research</button></div></div><div class="compact-list event-context-list">${kind!=='long'?`<div class="compact-row"><b>Earnings Risk</b><span>${titleCaseText(p.eventRisk)}</span></div>`:''}<div class="compact-row"><b>${deskRegimeName(kind)}</b><span>${regimeDisplayLabel(regime.label)} · ${regime.sentimentScore}/100</span></div><div class="compact-row"><b>Global Context</b><span>${esc(globalContextLine(p.sym,kind))}</span></div><div class="compact-row"><b>Options Context</b><span>${esc(optionsContextLine(p.sym,kind))}</span></div>${kind==='long'?`<div class="compact-row"><b>Earnings / Guidance Risk</b><span>${esc(earningsCompactLine(p.sym))}</span></div>`:''}<div class="compact-row data-source-context-row ${quoteAgeMs(p.sym)>1800000?'very-stale':''}"><b>Data State</b><span>${quoteAgeMs(p.sym)>1800000?'⚠ ':''}${esc(ds.label)} · ${esc(ds.detail||'')}</span></div><div class="compact-row"><b>Ticker News</b><span>${tickerNews.length} mapped headline${tickerNews.length===1?'':'s'}</span></div></div></section>`;
 const score=`<section class="card explainable-score-card"><div class="card-head"><div><h3>Explainable Score</h3><p>Grouped signals reduce duplicate weighting.</p></div><span class="score-pill ${p.tone}">${titleCaseText(p.direction)}</span></div><div class="factor-grid">${Object.entries(p.families).map(([k,v])=>`<div class="factor"><b><span>${esc(titleCaseText(k))}</span><span>${Math.round(v)}</span></b><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,v))}%"></div></div></div>`).join('')}</div></section>`;
 const side=kind==='day'?`${earn}${sec}${eventContext}${score}`:kind==='swing'?`${earn}${sec}${eventContext}${score}`:`${earn}${sec}${eventContext}${score}`;
 return `<div class="desk-detail-anchor" id="desk-detail-${kind}" data-detail-symbol="${esc(p.sym)}"><div class="detail-grid"><section class="card detail-main"><div class="detail-title"><div><span class="eyebrow">${deskCfg[kind].title} · ${deskCfg[kind].horizon}</span><h2>${p.sym} · ${titleCaseText(actionState(p))}</h2><p class="muted">${p.earnings.label} · Relative strength ${p.rs>=0?'+':''}${p.rs.toFixed(1)}</p></div><div class="detail-price"><small class="price-kicker">Last Price</small><strong>$${money(pc.live||p.price)}</strong><span class="${c.changePercent>=0?'positive':'negative'}">${pct(c.changePercent)}</span><div class="price-context"><span>${pc.closeLabel} <b>$${money(pc.close)}</b></span><span>Previous Close <b>$${money(pc.prev)}</b></span>${marketSession()==='overnight'&&num(c.bid)&&num(c.ask)?`<span>Bid / Ask <b>$${money(c.bid)} / $${money(c.ask)}</b></span>`:''}<span>Data <b>${esc(ds.label)} · ${esc(ds.detail||'')}</b></span></div></div></div><div class="plan-strip"><div class="plan-box zone-entry"><small>Entry Zone</small><strong>${rangeText(p.entry)}</strong></div><div class="plan-box zone-target"><small>Trim / Target</small><strong>${rangeText(p.target)}</strong></div><div class="plan-box zone-invalid"><small>Invalidation</small><strong>$${money(p.invalid)}</strong></div><div class="plan-box"><small>Setup Score</small><strong>${Math.round(p.score)} / 100</strong></div><div class="plan-box readiness-box"><small>Trade Readiness</small><strong>${esc(tradeReadiness(p.sym,kind).status)}</strong></div></div>${contextLens(p.sym,kind)}<div class="chart-wrap">${chartSVG(p)}</div>${stockKeyStatistics(p,kind)}</section><aside class="detail-side">${side}</aside></div>${tickerNewsPanel(p.sym)}</div>`
}
function watchlistContextTicker(sym){const qq=q(sym),st=quoteState(sym),price=num(qq.price),change=num(qq.changePercent);return `<div class="watchlist-market-ticker" title="${esc(st.label)} · ${esc(st.detail||'')}"><span>${statusDot(st.light,`${sym} ${st.label}`)}<b>${sym}</b></span><strong>${price?`$${money(price)}`:'—'}</strong><em class="${change>=0?'positive':'negative'}">${price?pct(change):'No Data'}</em></div>`}
function deskMembershipStrip(sym){const target=String(sym||'').toUpperCase(),items=[['day','DAY'],['swing','SWING'],['long','LONG']];return `<span class="desk-membership-strip" aria-label="Watchlist membership for ${esc(target)}">${items.map(([kind,label])=>{const active=(deskWL(kind).symbols||[]).includes(target);return `<i class="desk-membership-pill ${active?'active':''}" title="${active?`${target} is in ${kind==='long'?'Long-Term':kind==='day'?'Day Trade':'Swing'} watchlist`:`${target} is not in ${kind==='long'?'Long-Term':kind==='day'?'Day Trade':'Swing'} watchlist`}">${label}</i>`}).join('')}</span>`}
function discoveryMembership(sym,kind){const member=(deskWL(kind).symbols||[]).includes(sym),label=kind==='day'?'Day Trade':kind==='swing'?'Swing':'Long-Term';return member?`<button class="discovery-membership added" data-demote="${sym}:${kind}" title="Remove ${sym} from ${label}"><span>✓ ${label}</span><b aria-hidden="true">×</b></button>`:`<button class="btn tiny" data-promote="${sym}:${kind}">Add to ${label}</button>`}
function stagedCandidateRow(sym){const qq=q(sym),st=quoteState(sym),age=quoteAgeMs(sym),confirming=pendingRemoveEverywhere===sym;return `<article class="staged-candidate" data-staged-symbol="${sym}"><div class="staged-candidate-main"><div class="staged-symbol"><b>${sym}</b><span class="data-badge ${st.tone} ${st.label==='Demo'?'demo-badge':''}">${statusDot(st.light,`${st.label} ${sym}`)}${st.label}</span></div><div class="staged-live"><strong data-staged-price="${sym}">${num(qq.price)?`$${money(qq.price)}`:'—'}</strong><span data-staged-change="${sym}" class="${num(qq.changePercent)>=0?'positive':'negative'}">${num(qq.price)?pct(qq.changePercent):'No Data'}</span></div><small data-staged-freshness="${sym}">${esc(st.detail||ageText(age))}</small></div><div class="staged-actions"><div class="staged-memberships"><button class="btn tiny ghost" data-research="${sym}" data-research-origin="discovery">Research</button>${discoveryMembership(sym,'day')}${discoveryMembership(sym,'swing')}${discoveryMembership(sym,'long')}</div><button class="staged-close" data-remove-everywhere-request="${sym}" aria-label="Remove ${sym} from Discovery and all desk watchlists" title="Remove from Discovery and all desk watchlists">×</button></div>${confirming?`<div class="staged-confirm"><span>Remove ${sym} from Discovery and all desk watchlists?</span><div><button class="btn tiny ghost" data-remove-everywhere-cancel="${sym}">Cancel</button><button class="btn tiny danger" data-remove-everywhere-confirm="${sym}">Remove Everywhere</button></div></div>`:''}</article>`}
function deskWatchlistCard(kind,plans=[]){
  const wl=deskWL(kind),enabled=deskEnabled(kind),bySymbol=Object.fromEntries(plans.map(p=>[p.sym,p]));
  const deskLabel=kind==='swing'?'Swing':kind==='day'?'Day Trade':'Long-Term';
  const count=`${wl.symbols.length} symbol${wl.symbols.length===1?'':'s'}`;
  const rows=wl.symbols.map(sym=>{
    const p=enabled?(bySymbol[sym]||planFor(sym,kind)):null,qq=q(sym),st=quoteState(sym),light=p?setupLight(p):'yellow';
    const price=num(qq.price),change=num(qq.changePercent),setup=p?titleCaseText(actionState(p)):'Paused',score=p?Math.round(p.score):null;
    return `<div class="watchlist-list-row ${selected[kind]===sym?'selected':''}">
      <button class="watchlist-row-main compact" data-desk-symbol="${kind}:${sym}" title="Open ${sym} full analysis">
        <span class="watchlist-row-status">${statusDot(light,enabled?`${sym} ${setup}`:`${sym} saved; engine off`)}</span>
        <span class="watchlist-row-symbol"><b>${sym}</b><small>${esc(st.label)}</small></span>
        <span class="watchlist-row-price"><b>${price?`$${money(price)}`:'—'}</b></span>
        <span class="watchlist-row-change ${change>=0?'positive':'negative'}"><b>${price?pct(change):'—'}</b></span>
        <span class="watchlist-row-membership">${deskMembershipStrip(sym)}</span>
        <span class="watchlist-row-setup"><b>${esc(setup)}</b><small>${score===null?'Engine off':`${score} / 100`}</small></span>
      </button>
      <button class="watchlist-row-remove" data-desk-remove="${kind}:${wl.id}:${sym}" aria-label="Remove ${sym} from ${deskCfg[kind].title}" title="Remove ${sym}">×</button>
    </div>`;
  }).join('');
  return `<section class="card desk-watchlist-card v132-watchlist-card compact-desk-watchlist">
    <div class="v132-watchlist-toolbar compact-toolbar">
      <div class="v132-watchlist-title"><div><h2>${deskLabel} Watchlist <span class="watchlist-count-inline">${count}</span></h2><p>${deskCfg[kind].horizon} · Select a symbol for full analysis</p></div><div class="watchlist-engine-line">${statusDot(enabled?'green':'yellow',`Engine ${enabled?'On':'Off'}`)}<span>Engine ${enabled?'On':'Off'}</span></div></div>
      <div class="v132-watchlist-add compact-add"><div><input class="ticker-symbol-input" data-add-input="${kind}" value="${esc(watchlistDraft[kind]||'')}" placeholder="Ticker symbol" aria-label="Ticker symbol" maxlength="8" autocomplete="off" autocapitalize="characters" spellcheck="false"><button class="btn" data-add-desk="${kind}">Add</button></div></div>
    </div>
    <div class="v132-watchlist-context compact-context"><div class="watchlist-market-pair">${watchlistContextTicker('SPY')}${watchlistContextTicker('QQQ')}</div><div class="watchlist-legend">${enabled?`<span>${statusDot('green','Constructive')}Constructive</span><span>${statusDot('yellow','Watch')}Watch</span><span>${statusDot('red','Risk')}Risk</span>`:'<span class="muted">Engine Off</span>'}</div></div>
    <div class="v132-watchlist-list compact-list-view"><div class="watchlist-list-head"><span></span><span>Symbol</span><span>Price</span><span>Day</span><span>Desks</span><span>Setup / Score</span></div>${rows||'<div class="v132-watchlist-empty">No symbols yet. Use the ticker field above or the add row below.</div>'}</div>
  </section>`;
}
function deskAddTableRow(kind){return `<div class="desk-row desk-add-row" aria-label="Add symbol to ${deskCfg[kind].title}"><div class="desk-cell desk-add-symbol" data-label="Add Symbol"><input data-add-table-input="${kind}" value="${esc(watchlistDraft[kind]||'')}" placeholder="Ticker symbol" aria-label="Ticker symbol" maxlength="8" autocomplete="off" autocapitalize="characters" spellcheck="false"></div><div class="desk-cell desk-add-action" data-label="Action"><button class="btn" data-add-desk-table="${kind}">Add</button></div><div class="desk-cell desk-add-muted" aria-hidden="true"></div><div class="desk-cell desk-add-muted" aria-hidden="true"></div><div class="desk-cell desk-add-muted" aria-hidden="true"></div><div class="desk-cell desk-add-muted" aria-hidden="true"></div></div>`}
function renderDesk(kind){
 const wl=deskWL(kind),enabled=deskEnabled(kind);if(!selected[kind]||!wl.symbols.includes(selected[kind]))selected[kind]=wl.symbols[0]||'';
 if(!enabled)return `<div class="page desk-page">${pageHead(deskCfg[kind].title,deskCfg[kind].sub,'quotes','','none')}${deskRegimeControlGrid(kind)}<section class="card engine-disabled"><span>${statusDot('yellow','Engine is off')}</span><div><h2>${deskCfg[kind].title} Engine Is Off</h2><p>Watchlist saved. Desk calculations are paused. Shared symbols stay active when needed elsewhere.</p></div><button class="btn primary" data-engine-toggle="${kind}">Turn Engine On</button></section>${deskWatchlistCard(kind,[])}</div>`;
 const plans=sortPlans(wl.symbols.map(s=>planFor(s,kind)),kind),pick=plans.find(p=>p.sym===selected[kind])||plans[0],qualified=plans.filter(p=>p.score>=60).length,entry=plans.filter(p=>actionState(p)==='IN ENTRY ZONE').length,risk=plans.filter(p=>p.eventRisk==='HIGH').length;
 const kpis=kind==='long'?[['Qualified ≥60',qualified],['In Entry Zone',entry],['High Event Risk',risk],['Watchlist',wl.symbols.length]]:[['In Entry Zone',entry],['High Event Risk',risk],['Qualified ≥60',qualified],['Watchlist',wl.symbols.length]];
 return `<div class="page desk-page">${pageHead(deskCfg[kind].title,deskCfg[kind].sub,'quotes','','none')}${deskRegimeControlGrid(kind)}<div class="desk-kpis">${kpis.map(([l,v])=>`<div class="kpi"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div><section class="desk-table"><div class="desk-head"><div>Symbol / Price</div><div>Action / Score</div><div>Entry Zone</div><div>Trim / Target</div><div>Invalidation</div><div>Quality / Context</div></div>${plans.map(p=>deskRow(p,kind)).join('')}${deskAddTableRow(kind)}</section>${pick?detailCard(pick,kind):''}<section class="desk-watchlist-management"><div class="section-heading-row"><div><span class="eyebrow">Watchlist Management</span><h2>${deskCfg[kind].title} symbols</h2><p>Add, remove, or quickly select symbols after reviewing the active candidates above.</p></div></div>${deskWatchlistCard(kind,plans)}</section></div>`
}
function scannerModeTitle(mode){return mode==='day'?'Day Trade':mode==='swing'?'Swing':'Long-Term'}
function scannerPresetOptions(mode){return mode==='day'?[['top','Top Ranked'],['momentum','Momentum'],['gappers','Gappers'],['volume','High Volume']]:mode==='swing'?[['trend','Trend'],['momentum','Momentum'],['pullback','Pullback'],['top','Top Ranked']]:[['quality','Quality + Trend'],['trend','Long-Term Trend'],['top','Top Ranked']]}
function filteredDiscoveryResults(results,mode){const f=discoveryFilters[mode]||{},preset=discoveryPreset[mode]||'top';return (results||[]).filter(x=>{if(num(x.price)<num(f.minPrice))return false;if(num(x.score)<num(f.minScore))return false;if(num(x.spreadPercent)>num(f.maxSpread))return false;if(mode==='day'&&num(f.minRvol)>0&&num(x.relativeVolume)<num(f.minRvol))return false;if(mode==='swing'&&num(x.trendScore)<num(f.minTrend??-100))return false;if(mode==='long'&&num(f.minFundamental)>0&&num(x.fundamentalScore)>0&&num(x.fundamentalScore)<num(f.minFundamental))return false;if(preset==='momentum')return Math.abs(num(x.changePercent))>=2||num(x.momentumScore)>=25;if(preset==='gappers')return Math.abs(num(x.gapPercent))>=1.5;if(preset==='volume')return num(x.relativeVolume)>=1.25;if(preset==='trend')return num(x.trendScore)>=35;if(preset==='pullback')return num(x.trendScore)>=30&&num(x.changePercent)<=.75;if(preset==='quality')return num(x.fundamentalScore)>=60||(num(x.fundamentalScore)===0&&num(x.trendScore)>=50);return true})}
function scannerFiltersUI(mode){const f=discoveryFilters[mode],special=mode==='day'?`<div class="field compact"><label>Min RVOL</label><input type="number" step="0.1" min="0" data-discovery-filter="minRvol" value="${num(f.minRvol)}"></div>`:mode==='swing'?`<div class="field compact"><label>Min Trend</label><input type="number" step="5" min="-100" max="100" data-discovery-filter="minTrend" value="${num(f.minTrend)}"></div>`:`<div class="field compact"><label>Min Fundamental</label><input type="number" step="5" min="0" max="100" data-discovery-filter="minFundamental" value="${num(f.minFundamental)}"></div>`;return `<div class="scanner-filter-grid"><div class="field compact"><label>Preset</label><select data-scan-preset="${mode}">${scannerPresetOptions(mode).map(([v,l])=>`<option value="${v}" ${discoveryPreset[mode]===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field compact"><label>Min Price</label><input type="number" min="0" step="1" data-discovery-filter="minPrice" value="${num(f.minPrice)}"></div><div class="field compact"><label>Min Score</label><input type="number" min="0" max="100" step="5" data-discovery-filter="minScore" value="${num(f.minScore)}"></div><div class="field compact"><label>Max Spread %</label><input type="number" min="0" step="0.05" data-discovery-filter="maxSpread" value="${num(f.maxSpread)}"></div>${special}</div>`}
function discoveryRankLabel(score){const n=num(score);return n>=75?'Strong':n>=62?'Qualified':n>=52?'Watch':'Weak'}
function scannerTable(mode,results,watched){
 const modeLabel=scannerModeTitle(mode),head=mode==='day'?['Symbol','Price','Discovery Rank','Move','Gap','RVOL','Liquidity / Spread','Desks','Actions']:mode==='swing'?['Symbol','Price','Discovery Rank','Trend','RVOL','Why','Desks','Actions']:['Symbol','Price','Discovery Rank','Fundamental','Trend','Why','Desks','Actions'];
 const actions=x=>{const inDesk=(deskWL(mode).symbols||[]).includes(String(x.symbol||'').toUpperCase());return `<div class="scanner-actions"><button class="btn small ${watched.has(x.symbol)?'ghost':''}" data-add-discovery="${esc(x.symbol)}" ${watched.has(x.symbol)?'disabled':''}>${watched.has(x.symbol)?'Staged':'Stage'}</button><button class="btn small ghost" data-research="${esc(x.symbol)}" data-research-origin="discovery">Research</button><button class="btn small ${inDesk?'ghost':''}" data-promote="${esc(x.symbol)}:${mode}" ${inDesk?'disabled':''}>${inDesk?'In '+modeLabel:'Add to '+modeLabel}</button></div>`};
 const symbolCell=x=>{const raw=(x.reasons||[]).slice(0,2).join(' · ')||'Candidate';return `<span class="scanner-cell scanner-symbol-cell"><b>${esc(x.symbol)}</b><small title="${esc(raw)}">${esc(raw)}</small></span>`};
 const rankCell=x=>`<span class="scanner-cell discovery-rank-cell"><b>${Math.round(num(x.score))}/100</b><small>${esc(discoveryRankLabel(x.score))}</small></span>`;
 const deskCell=x=>`<span class="scanner-cell scanner-desk-cell">${deskMembershipStrip(x.symbol)}</span>`;
 const actionCell=x=>`<span class="scanner-cell scanner-action-cell">${actions(x)}</span>`;
 const row=x=>{const reasons=(x.reasons||[]).slice(0,2).join(' · ')||'Candidate';if(mode==='day')return `<div class="scanner-row scanner-row-day">${symbolCell(x)}<span class="scanner-cell scanner-price-cell">$${money(x.price)}</span>${rankCell(x)}<span class="scanner-cell scanner-number-cell ${num(x.changePercent)>=0?'positive':'negative'}">${pct(x.changePercent)}</span><span class="scanner-cell scanner-number-cell">${pct(x.gapPercent)}</span><span class="scanner-cell scanner-number-cell">${num(x.relativeVolume)?num(x.relativeVolume).toFixed(2)+'×':'—'}</span><span class="scanner-cell scanner-liquidity-cell"><b>${dollarText(x.dollarVolume)}</b><small>${num(x.spreadPercent).toFixed(2)}% spread</small></span>${deskCell(x)}${actionCell(x)}</div>`;if(mode==='swing')return `<div class="scanner-row scanner-row-swing">${symbolCell(x)}<span class="scanner-cell scanner-price-cell">$${money(x.price)}</span>${rankCell(x)}<span class="scanner-cell scanner-number-cell ${num(x.trendScore)>=0?'positive':'negative'}">${num(x.trendScore).toFixed(0)}</span><span class="scanner-cell scanner-number-cell">${num(x.relativeVolume)?num(x.relativeVolume).toFixed(2)+'×':'—'}</span><span class="scanner-cell scanner-why-cell"><small title="${esc(reasons)}">${esc(reasons)}</small></span>${deskCell(x)}${actionCell(x)}</div>`;return `<div class="scanner-row scanner-row-long">${symbolCell(x)}<span class="scanner-cell scanner-price-cell">$${money(x.price)}</span>${rankCell(x)}<span class="scanner-cell scanner-number-cell">${num(x.fundamentalScore)?Math.round(num(x.fundamentalScore))+'/100':'Pending'}</span><span class="scanner-cell scanner-number-cell ${num(x.trendScore)>=0?'positive':'negative'}">${num(x.trendScore).toFixed(0)}</span><span class="scanner-cell scanner-why-cell"><small title="${esc(reasons)}">${esc(reasons)}</small></span>${deskCell(x)}${actionCell(x)}</div>`};
 return `<div class="scanner-table scanner-table-${mode}"><div class="scanner-head scanner-head-${mode}">${head.map(h=>`<span>${h}</span>`).join('')}</div>${results.map(row).join('')||'<div class="empty">No candidates match the current scanner filters.</div>'}</div>`
}

function renderDiscovery(){
 const scan=runtime?.scanner||{mode:discoveryMode,status:'idle',results:[]},mode=scan.mode||discoveryMode;discoveryMode=mode;const allResults=scan.results||[],results=filteredDiscoveryResults(allResults,mode),wl=discoveryWL(),watched=new Set(wl.symbols||[]),modeTitle=scannerModeTitle(mode),purpose=mode==='day'?'Find liquid session movers with gap/extended-hours momentum and relative-volume confirmation.':mode==='swing'?'Find 5–20 session trend and participation candidates.':'Find long-horizon trend candidates and qualify business quality when fundamentals are available.';
 return `<div class="page discovery-page" data-scope-marker="discovery-market-scanner-v1421">${pageHead('Discovery','Find candidates, stage them, then move to Research or the appropriate trading desk.','scanner','','none')}<section class="scanner-command card"><div class="scanner-summary"><span class="eyebrow">Discovery Horizon</span><h2>${modeTitle} Discovery</h2><p>${purpose}</p><small class="scanner-meta">${scan.updatedAt?`${scan.scanned||0} scanned · ${allResults.length} ranked · ${timePair(scan.updatedAt)}`:'Choose a horizon, set the scan criteria, then run the market scan.'}</small></div><div class="scanner-modes">${[['day','Day Trade'],['swing','Swing'],['long','Long-Term']].map(([k,label])=>`<button class="scanner-mode ${mode===k?'active':''}" data-scan-mode="${k}">${label}</button>`).join('')}</div><div class="scanner-setup-heading"><span class="eyebrow">Scan Setup</span><p>Filters remain fully visible because they define the candidate universe.</p></div>${scannerFiltersUI(mode)}<div class="scanner-run-row"><button class="btn primary" data-run-scan="${mode}" ${scan.status==='running'?'disabled':''}>${scan.status==='running'?'Scanning…':'Run Market Scan'}</button><button class="btn ghost" data-view-staged>Staged (${wl.symbols.length})</button></div></section><section class="discovery-funnel"><div><small>Scanned</small><b>${scan.scanned||0}</b></div><div><small>Ranked</small><b>${allResults.length}</b></div><div><small>Qualified</small><b>${results.length}</b></div><div><small>Staged</small><b>${wl.symbols.length}</b></div></section>${runtime?.marketActivity?.status==='AVAILABLE'?`<section class="card discovery-market-activity full-width"><div class="card-head"><div><span class="eyebrow">Live Market Activity Seeds</span><h3>Most active / movers</h3><p>Discovery context only; these do not bypass horizon filters or deterministic desk scoring.</p></div><span class="data-badge live">AVAILABLE</span></div><div class="market-activity-seeds">${[...(runtime.marketActivity.mostActive||[]).slice(0,5),...(runtime.marketActivity.gainers||[]).slice(0,3)].filter((x,i,a)=>a.findIndex(y=>y.symbol===x.symbol)===i).map(x=>`<span><b>${esc(x.symbol)}</b><small>${num(x.changePercent)?pctSigned(x.changePercent):'Active'}</small></span>`).join('')||'<div class="empty">No entitled activity seed data.</div>'}</div></section>`:''}<section class="card scanner-results full-width"><div class="card-head"><div><h2>${modeTitle} Candidates</h2><p>Discovery Rank is candidate priority only. The desk's deterministic Action/Score remains the setup decision model.</p></div><span class="count-pill">${results.length}</span></div>${scan.status==='running'?'<div class="empty">Scanning the US equity universe…</div>':scannerTable(mode,results,watched)}</section><section id="staged-candidates" class="card discovery-watchlist full-width"><div class="card-head"><div><span class="eyebrow">Staged Candidates</span><h2>Research or assign a horizon</h2><p>Research comes first in the action flow; desk assignment remains available without creating duplicate subscriptions.</p></div><strong>${wl.symbols.length}</strong></div><div class="discovery-watch-items">${wl.symbols.map(stagedCandidateRow).join('')||'<div class="empty">No candidates are staged yet.</div>'}</div></section></div>`
}
function renderNews(){const items=runtime?.news||[];return `<div class="page news-page">${pageHead('News','Market and company news for your watchlists.','news','', 'none')}<div class="news-grid">${items.map(n=>`<article class="feed-card"><div class="meta"><span>${esc(n.source||'News')}</span><span>${new Date(num(n.datetime)*1000).toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</span></div><h3>${esc(n.headline)}</h3><p>${esc(n.summary||'No summary available.')}</p>${n.url?`<button class="btn small ghost feed-action" data-url="${esc(n.url)}">Open Source</button>`:''}</article>`).join('')||'<div class="empty">No news available.</div>'}</div></div>`}
function renderEarnings(){const items=[...(runtime?.earnings||[])].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));return `<div class="page earnings-page">${pageHead('Earnings','Expectations before the event; expected vs actual, surprise, guidance, and reaction context after it.','earnings','', 'none')}<div class="event-grid earnings-event-grid">${items.map(e=>{const target=String(e.symbol||'').toUpperCase(),reported=e.epsActual!=null||e.revenueActual!=null,g=guidanceSignal(target);return `<article class="event-card earnings-event-card ${reported?'reported':'upcoming'}"><div class="meta"><span>${reported?'REPORTED':esc(String(e.hour||'TBD').toUpperCase())}</span><span>${dateOnly(e.date)}</span></div><h3>${esc(target)}</h3>${reported?`<div class="earnings-result-grid"><span><small>EPS</small><b>${esc(earningsBeatLabel(e.epsActual,e.epsEstimate))}</b><em>${e.epsEstimate==null?'—':`Exp ${num(e.epsEstimate).toFixed(2)} · Act ${e.epsActual==null?'—':num(e.epsActual).toFixed(2)}`}</em></span><span><small>Revenue</small><b>${esc(earningsBeatLabel(e.revenueActual,e.revenueEstimate))}</b><em>${e.revenueEstimate==null?'—':`Exp $${compactNumber(e.revenueEstimate)} · Act ${e.revenueActual==null?'—':'$'+compactNumber(e.revenueActual)}`}</em></span><span><small>Guidance</small><b class="${g.tone}">${esc(titleCaseText(g.status))}</b><em>${g.evidence?esc(g.evidence.source):'No explicit guidance evidence'}</em></span></div>`:`<div class="event-metrics"><span><small>EPS Expected</small><b>${e.epsEstimate==null?'—':num(e.epsEstimate).toFixed(2)}</b></span><span><small>Revenue Expected</small><b>${e.revenueEstimate==null?'—':'$'+compactNumber(e.revenueEstimate)}</b></span></div>`}<div class="button-row"><button class="btn tiny ghost" data-research="${esc(target)}" data-research-origin="earnings">Research</button></div></article>`}).join('')||'<div class="empty">No earnings data available.</div>'}</div></div>`}
const SEC_FORM_GUIDE=[
 ['8-K','Material Company Update'],
 ['10-Q','Quarterly Report'],
 ['10-K','Annual Report'],
 ['4','Insider Buy / Sell / Other'],
 ['13F','Institutional Holdings Report'],
 ['13D/G','Major Shareholder Disclosure'],
 ['S-1','Registration / IPO Filing'],
 ['S-3/424B','Share Offering / Registration'],
 ['DEF 14A','Proxy Statement']
];
function secFormKey(form){const f=String(form||'').toUpperCase().replace('/A','');if(f.startsWith('13F'))return '13F';if(f.includes('13D')||f.includes('13G'))return '13D/G';if(f==='S-1')return 'S-1';if(f==='S-3'||f.startsWith('424B'))return 'S-3/424B';return f}
function secFormMeaning(form){const k=secFormKey(form),m=Object.fromEntries(SEC_FORM_GUIDE);return m[k]||({'6-K':'Foreign Issuer Update','20-F':'Foreign Annual Report','144':'Planned Insider Sale','DEF 14A':'Proxy Statement','S-1':'Registration / IPO Filing'})[k]||'SEC Filing'}
function secFilingMeaning(f){if(!f)return 'SEC Filing';const form=secFormKey(f.form),sig=String(f.signal||'').toUpperCase();if(form==='4'&&sig)return `Insider ${sig}`;return f.meaning||secFormMeaning(f.form)}
function secFilingDetail(f){if(!f)return '';const parts=[];if(f.actor)parts.push(f.actor);if(f.role)parts.push(f.role);if(f.transactionType)parts.push(f.transactionType);if(num(f.shares))parts.push(`${Math.round(num(f.shares)).toLocaleString()} shares`);if(num(f.price))parts.push(`$${money(f.price)} avg`);if(num(f.value))parts.push(secMoney(f.value));if(num(f.ownershipAfter))parts.push(`${Math.round(num(f.ownershipAfter)).toLocaleString()} owned after`);return parts.join(' · ')}
function secMoney(v){const n=num(v);if(!n)return '';if(n>=1e6)return '$'+(n/1e6).toFixed(n>=1e7?0:1)+'M';if(n>=1e3)return '$'+Math.round(n/1e3)+'K';return '$'+Math.round(n)}
function secIntelRow(label,value,tone=''){return `<div class="sec-intel-row"><span>${esc(label)}</span><b class="${tone}">${esc(value||'—')}</b></div>`}
function secIntelligenceSummary(sym){const x=runtime?.secIntelligence?.[sym];if(!x)return `<section class="card sec-intelligence-card"><div class="card-head"><div><h3>SEC Intelligence Summary</h3><p>Long-horizon filing, ownership, insider, and offering context.</p></div></div><div class="sec-intel-empty">${state?.settings?.secEmail?'Waiting for SEC EDGAR data.':'Add SEC contact email in Settings.'}</div><button class="btn small ghost" data-research="${esc(sym)}" data-research-origin="long">Open Filings in Research</button></section>`;const insider=x.insiderBuys||x.insiderSells?`${x.insiderBuys||0} Buy${x.insiderBuys===1?'':'s'} · ${x.insiderSells||0} Sell${x.insiderSells===1?'':'s'}`:'No recent insider transaction',ownership=x.ownershipChanges?`${x.ownershipChanges} recent`:'No recent change',material=x.materialEvents?`${x.materialEvents} recent`:'None recent',latest=x.latestForm?`${secFormMeaning(x.latestForm)} · ${x.latestForm} · ${x.latestFiledAt?dateOnly(x.latestFiledAt):'—'}`:'—',risk=x.offeringRisk||'Low',riskTone=risk==='High'?'negative':risk==='Watch'?'warning':'positive';return `<section class="card sec-intelligence-card"><div class="card-head"><div><h3>SEC Intelligence Summary</h3><p>Long-horizon SEC evidence for ${esc(sym)}.</p></div></div><div class="sec-intel-grid">${secIntelRow('Insiders',insider,x.insiderBuys>x.insiderSells?'positive':x.insiderSells>x.insiderBuys?'negative':'')}${secIntelRow('Institutions',x.institutional||'Quarterly institutional reporting')}${secIntelRow('Ownership',ownership)}${secIntelRow('Material Updates',material)}${secIntelRow('Offering Risk',risk,riskTone)}${secIntelRow('Latest Filing',latest)}</div>${(x.signals||[]).length?`<div class="sec-signal-list">${x.signals.slice(0,3).map(z=>`<button class="sec-signal ${esc(z.tone||'neutral')}" ${z.url?`data-url="${esc(z.url)}"`:''}><span>${esc(z.label||'SEC')}</span><b>${esc(z.detail||'')}</b><small>${esc(z.date||'')}</small></button>`).join('')}</div>`:''}<button class="btn small ghost sec-details-button" data-research="${esc(sym)}" data-research-origin="long">Open Filings in Research</button></section>`}
function renderFilings(){const guide=SEC_FORM_GUIDE.map(([f,m])=>`<span class="sec-guide-chip"><b>${esc(m)}</b><span>${esc(f)}</span></span>`).join(''),items=runtime?.filings||[];return `<div class="page sec-page">${pageHead('SEC Filings','Recent filing intelligence for active symbols. Friendly names are primary; form codes are reference.','filings','', 'none')}<section class="card sec-form-guide"><div><span class="eyebrow">SEC Filing Guide</span><h2>What the filings mean</h2></div><div class="sec-guide-list">${guide}</div></section><div class="event-grid sec-event-grid">${items.map(f=>`<article class="event-card sec-filing-card"><div class="meta"><span class="filing-form"><b>${esc(secFilingMeaning(f))}</b> <i>${esc(f.form)}</i></span><span>${dateOnly(f.filedAt)}</span></div><h3>${esc(f.symbol)} · ${esc(f.company||'')}</h3><p>${esc(f.description||f.meaning||secFormMeaning(f.form))}</p>${secFilingDetail(f)?`<small class="sec-transaction-detail">${esc(secFilingDetail(f))}</small>`:''}${f.signal?`<div class="filing-signal ${String(f.signal).toLowerCase()}"><b>${esc(String(f.signal).toUpperCase())}</b>${f.role?`<span>${esc(f.role)}</span>`:''}${num(f.value)?`<strong>${esc(secMoney(f.value))}</strong>`:''}</div>`:''}<button class="btn small ghost feed-action" data-url="${esc(f.url)}">Open SEC Filing</button></article>`).join('')||'<div class="empty">Add an SEC contact email in Settings to load filings. No SEC account or API key is needed.</div>'}</div></div>`}
const AI_PROVIDER_META={
  groq:{id:'groq',name:'Groq AI',short:'GROQ',role:'Primary',model:'GPT-OSS 120B',setting:'groqModel',keyFlag:'hasGroqKey',keyHint:'groqKeyHint'},
  openrouter:{id:'openrouter',name:'OpenRouter',short:'OPENROUTER',role:'Secondary',model:'Fast',setting:'openRouterMode',keyFlag:'hasOpenRouterKey',keyHint:'openRouterKeyHint'},
  gemini:{id:'gemini',name:'Google Gemini',short:'GEMINI',role:'Backup',model:'Gemini 3.1 Flash-Lite',setting:'geminiModel',keyFlag:'hasGeminiKey',keyHint:'geminiKeyHint'}
};
const OPENROUTER_MODELS={
 fast:{label:'FAST',summary:'GPT-5.6 Luna → Grok 4.20 → Claude Haiku 4.5'},
 balanced:{label:'BALANCED',summary:'Grok 4.20 → GPT-5.6 Terra → Claude Sonnet 5'},
 powerful:{label:'POWERFUL',summary:'Claude Sonnet 5 → GPT-5.6 Sol → Grok 4.5'},
 specific:{label:'SPECIFIC',summary:'Use the selected GPT, Grok, or Claude model'}
};
function modelDisplayName(model){const m=String(model||'').replace(/^~?anthropic\//,'').replace(/^openai\//,'').replace(/^x-ai\//,'');return ({'gpt-5.6-luna':'GPT-5.6 Luna','gpt-5.6-terra':'GPT-5.6 Terra','gpt-5.6-sol':'GPT-5.6 Sol','grok-4.20':'Grok 4.20','grok-4.5':'Grok 4.5','claude-haiku-4.5':'Claude Haiku 4.5','claude-sonnet-5':'Claude Sonnet 5','gpt-oss-120b':'GPT-OSS 120B','gemini-3.1-flash-lite':'Gemini 3.1 Flash-Lite'})[m]||m||'AI model'}
function openRouterMode(){const m=String(state?.settings?.openRouterMode||'fast').toLowerCase();return OPENROUTER_MODELS[m]?m:'fast'}
function openRouterModeInfo(){return OPENROUTER_MODELS[openRouterMode()]||OPENROUTER_MODELS.fast}
function activeAIProvider(){const id=String(state?.settings?.aiProvider||'groq').toLowerCase();return AI_PROVIDER_META[id]?id:'groq'}
function aiProviderMeta(id=activeAIProvider()){return AI_PROVIDER_META[id]||AI_PROVIDER_META.groq}
function aiProviderConfigured(id){const m=aiProviderMeta(id);return !!state?.[m.keyFlag]}
function aiProviderState(id){const p=state?.providerStatus?.[id];if(!aiProviderConfigured(id))return {label:'NOT CONFIGURED',light:'yellow',detail:'Add an API key in Settings.'};if(p?.ok)return {label:'READY',light:'green',detail:p.message||'Connection verified.'};if(p&&p.status==='billing required')return {label:'BILLING REQUIRED',light:'red',detail:p.message||'API billing is required.'};if(p&&p.status==='rate limited')return {label:'RATE LIMITED',light:'yellow',detail:p.message||'Current provider rate limit reached.'};if(p&&!p.ok)return {label:'CHECK CONNECTION',light:'red',detail:p.message||'Connection test failed.'};return {label:'CONFIGURED',light:'cyan',detail:'API key saved. Run Save & Test to verify.'}}
function aiProviderDisplay(id=activeAIProvider()){if(id==='openrouter'){const info=openRouterModeInfo();return {name:'OpenRouter',model:`${info.label} · ${info.summary}`}}const meta=aiProviderMeta(id),model=state?.settings?.[meta.setting]||meta.model;return {name:meta.name,model:modelDisplayName(model)}}

function aiHorizonLabel(h){return h==='day'?'Day Trade':h==='swing'?'Swing':h==='long'?'Long-Term':'Cross-Horizon Research'}

function aiContextSummaryMarkup(sym){const h=aiOriginHorizon,label=aiHorizonLabel(h),ctx=buildAIClientContext(sym,h);let score='Cross-horizon';if(['day','swing','long'].includes(h)&&ctx.deterministic)score=`${Math.round(ctx.deterministic.score)}/100 · ${titleCaseText(actionState(ctx.deterministic))}`;return `<section class="ai-context-received"><div><small>Received context</small><b>${esc(aiOrigin==='research'?'Research':aiOrigin==='day'?'Day Trade':aiOrigin==='swing'?'Swing':aiOrigin==='long'?'Long-Term':aiOrigin==='discovery'?'Discovery':'Dashboard')} → ${esc(label)}</b></div><div><small>Deterministic setup</small><b>${esc(score)}</b></div><div><small>Earnings</small><b>${esc(earningsCompactLine(sym))}</b></div><div><small>Evidence freshness</small><b>${esc(quoteState(sym).label)}</b></div></section>`}
async function runAIRequest(kind='ticker'){const qtext=$('#ai-question')?.value||'',out=$('#ai-output'),meta=$('#ai-response-meta'),sym=String(aiSymbol||state?.ui?.selectedTicker||'SPY').toUpperCase(),horizon=aiOriginHorizon||'none',key=aiResultKey(sym,horizon,kind,qtext);$$('[data-ai]').forEach(x=>x.classList.toggle('primary',x.dataset.ai===kind));const cached=aiResearchResults[key];if(cached){cached._generatedAt=Date.now();render();const m=$('#ai-response-meta');if(m)m.textContent=`Cached ${kind==='risk'?'Risk Review':kind==='news'?'Catalyst Review':kind==='custom'?'Custom Question':'Research Confirmation'} · evidence unchanged`;return}const activeBtn=$('[data-ai-run-review]');if(activeBtn){activeBtn.disabled=true;activeBtn.dataset.originalText=activeBtn.textContent;activeBtn.textContent='Analyzing…'}if(out)out.innerHTML=`<div class="empty">Analyzing ${esc(sym)} ${esc(aiHorizonLabel(horizon))} context…</div>`;if(meta)meta.textContent=`Using ${aiProviderMeta().name}…`;try{const clientContext=buildAIClientContext(sym,horizon),res=await api('/api/ai/generate',{kind:kind==='custom'?'':kind,question:qtext,ticker:sym,scopeType:'watchlist',watchlistId:['day','swing','long'].includes(horizon)?deskWL(horizon).id:deskWL('swing').id,clientContext});aiResearchResults[key]={...res,_symbol:sym,_horizon:horizon,_reviewType:kind,_question:kind==='custom'?qtext:'',_generatedAt:Date.now(),_fingerprint:aiEvidenceFingerprint(sym,horizon)};render();const m=$('#ai-response-meta');if(m)m.textContent=aiResponseMetaText(res)}catch(e){if(out)out.innerHTML=`<div class="empty negative">${esc(e.message||'AI review could not be completed.')}</div>`;if(meta)meta.textContent=`${aiProviderMeta().name} · Request failed`}finally{const b=$('[data-ai-run-review]');if(b){b.disabled=false;if(b.dataset.originalText)b.textContent=b.dataset.originalText}}}
function openAIFor(sym,origin='research',horizon='none',autoRun=true){aiSymbol=String(sym||state?.ui?.selectedTicker||'SPY').toUpperCase();aiOrigin=origin||'research';aiOriginHorizon=['day','swing','long'].includes(horizon)?horizon:'none';aiReviewMode='ticker';aiAutoRun=!!autoRun;api('/api/ui/ticker',{symbol:aiSymbol}).catch(()=>{});setPage('ai')}
function aiResultMarkup(sym){const r=latestAIResultFor(sym);if(!r)return `<div id="ai-output" class="ai-result-empty">The selected symbol and horizon evidence are preloaded. Run Research Confirmation for a concise second opinion.</div>`;const horizon=r.bestFitHorizon,hl=aiHorizonLabel(horizon),verdict=titleCaseText(r.verdict||'Informational');return `<section id="ai-output" class="ai-result-card ${String(r.verdict||'informational').toLowerCase()}"><div class="ai-verdict-row"><div><span class="eyebrow">${esc(r._reviewType==='risk'?'Risk Review':r._reviewType==='news'?'Catalyst Review':r._reviewType==='custom'?'Custom Question':'Research Confirmation')}</span><h2>${esc(verdict)}</h2><p>${esc(r.summary||r.nextAction||'Review completed.')}</p></div><div class="ai-confidence"><small>Confidence</small><b>${Math.round(num(r.confidence))}%</b></div></div><div class="ai-result-grid"><div><small>Best-fit horizon</small><b>${esc(hl)}</b></div><div><small>Key reasons</small><ul>${(r.reasons||[]).slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>None supplied</li>'}</ul></div><div><small>Risks</small><ul>${(r.risks||[]).slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>None identified</li>'}</ul></div><div><small>Catalyst</small><b>${esc(r.catalyst||'None identified')}</b></div></div><div class="button-row ai-next-actions"><button class="btn ghost" data-ai-open-research="${esc(sym)}">Open Research</button>${['day','swing','long'].includes(horizon)?`<button class="btn primary" data-ai-open-desk="${horizon}:${esc(sym)}">Open ${esc(hl)}</button>${!(deskWL(horizon).symbols||[]).includes(sym)?`<button class="btn" data-ai-add-desk="${horizon}:${esc(sym)}">Add to ${esc(hl)}</button>`:''}`:''}</div>${r.details?`<details class="ai-evidence"><summary>Evidence & details</summary><p>${esc(r.details)}</p></details>`:''}<p class="research-footnote">AI is advisory. It cannot trade, change Action/Score, or add/remove a symbol without your explicit click.</p></section>`}
function renderAI(){
 const id=activeAIProvider(),meta=aiProviderMeta(id),st=aiProviderState(id),display=aiProviderDisplay(id),mode=id==='openrouter'?openRouterModeInfo().label:'',sym=String(aiSymbol||state?.ui?.selectedTicker||'SPY').toUpperCase(),symbols=allResearchSymbols(),reviewLabel=aiReviewMode==='risk'?'Risk Review':aiReviewMode==='news'?'Catalyst Review':aiReviewMode==='custom'?'Custom Question':'Research Confirmation',originLabel=aiOrigin==='research'?'Research':aiOrigin==='day'?'Day Trade':aiOrigin==='swing'?'Swing':aiOrigin==='long'?'Long-Term':aiOrigin==='discovery'?'Discovery':'Dashboard';
 const reviews=[['ticker','Research Confirmation'],['risk','Risk Review'],['news','Catalyst Review'],['custom','Custom Question']];
 return `<div class="page ai-page">${pageHead('AI Copilot','A context-aware second opinion on the symbol you were already reviewing.','ai','','none')}<section class="card ai-engine-card ai-engine-${id}"><div class="ai-engine-main"><div class="ai-engine-orb ${st.light}"><span></span><i></i></div><div class="ai-engine-copy"><span class="eyebrow">AI Engine</span><h2>${esc(meta.name)} <small>${esc(meta.role)}</small></h2><p>${id==='openrouter'?`${esc(mode)} · ${esc(openRouterModeInfo().summary)}`:esc(display.model)}</p></div></div><div class="ai-engine-state"><span>${statusDot(st.light,st.label)}${esc(st.label)}</span><small>${esc(st.detail)}</small></div><button class="btn ghost" data-jump="settings" data-settings-target="ai-integration">Manage AI</button></section><section class="card ai-workspace"><div class="ai-target-section"><span class="eyebrow">Research Target</span><div class="ai-target-paths"><label><small>Choose from List</small><select data-ai-symbol aria-label="Choose AI research target">${symbols.map(s=>`<option value="${esc(s)}" ${s===sym?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label><small>Add Symbol</small><span><input data-ai-symbol-input placeholder="Ticker" maxlength="8" aria-label="Enter any ticker"><button class="btn tiny" data-ai-symbol-load>Load</button></span></label></div><h2>${esc(sym)} · ${esc(aiHorizonLabel(aiOriginHorizon))}</h2><p>Opened from ${esc(originLabel)}. Context is preloaded; verify the received context below before asking AI to review it.</p></div>${aiContextSummaryMarkup(sym)}<section class="ai-review-workspace"><div class="ai-review-heading"><div><span class="eyebrow">Choose Review</span><h3>What should AI validate?</h3><p>Optional question appears when Custom Question is selected.</p></div></div><div class="ai-review-selector">${reviews.map(([k,l])=>`<button class="ai-review-choice ${aiReviewMode===k?'active':''}" data-ai-review-choice="${k}">${l}</button>`).join('')}</div>${aiReviewMode==='custom'?`<div class="field ai-custom-question"><label>Custom Question</label><textarea id="ai-question" rows="3" placeholder="What is the biggest reason this setup could fail?"></textarea></div>`:`<textarea id="ai-question" hidden></textarea>`}<div class="ai-run-row"><button class="btn primary" data-ai-run-review="${aiReviewMode}">Run ${esc(reviewLabel)}</button><span class="ai-active-provider">Using ${esc(meta.name)}${mode?' · '+esc(mode):''}</span></div></section>${aiResultMarkup(sym)}<div id="ai-response-meta" class="ai-response-meta">Provider: ${esc(meta.name)}${id==='openrouter'?' · '+esc(mode):' · '+esc(display.model)}</div></section></div>`
}
function aiResponseMetaText(res){const provider=res.providerLabel||aiProviderMeta(res.provider).name,actual=modelDisplayName(res.model),parts=[];if(res.provider==='openrouter'){parts.push(`Answered by ${actual}`);if(res.mode)parts.push(String(res.mode).toUpperCase());if(num(res.latencyMs))parts.push(`${(num(res.latencyMs)/1000).toFixed(1)}s`);const tokens=num(res.inputTokens)+num(res.outputTokens);if(tokens)parts.push(`${tokens.toLocaleString()} tokens`);if(num(res.cost))parts.push(`$${num(res.cost).toFixed(4)}`);if(res.fallback)parts.push('Fallback used');return parts.join(' · ')}return `Generated with ${provider} · ${actual}`}
function providerStatus(name){const p=state?.providerStatus?.[name];if(!p)return '<div class="status-box muted">Not tested in this installation.</div>';return `<div class="status-box ${p.ok?'positive':'negative'}"><b>${esc(titleCaseText(p.status))}</b> · ${esc(p.message)}<br><span class="muted">${timePair(Date.parse(p.checkedAt))}</span></div>`}
function fmtBytes(n){n=num(n);return n>=1048576?`${(n/1048576).toFixed(1)} MB`:n>=1024?`${(n/1024).toFixed(1)} KB`:`${n||0} B`}
function vixDiagnosticsCard(){const vx=q('VIX'),health=String(runtime?.health?.vix||'Not initialized'),last=num(runtime?.lastUpdated?.vix),source=String(vx.source||'');let sourceLabel='Unavailable';if(source.startsWith('finnhub-vix:'))sourceLabel='Finnhub direct index';else if(source.startsWith('twelvedata-vix:'))sourceLabel='Twelve Data direct index';else if(source==='cboe-vix-official-close')sourceLabel='Cboe official close';else if(source&&num(vx.price))sourceLabel=source.includes('cache')?'Real cache':source;const tone=sidebarHealthTone(health),stateText=num(vx.price)?`${money(vx.price)} · ${sourceLabel}`:'Unavailable';return `<div class="vix-diagnostic-card"><span>${statusDot(tone==='green'?'green':tone==='red'?'red':'yellow','VIX')}VIX</span><b>${esc(stateText)}</b><small>${esc(health)}${last?' · '+esc(timePair(last)):''}</small></div>`}
function feedDiagnostics(){const f=runtime?.feed||{},lastFinnhub=num(f.lastTradeAt),lastAlpaca=num(f.lastAlpacaAt),lastAlpacaStream=num(f.lastAlpacaStreamAt),count=(f.subscribedSymbols||[]).length,alpacaCount=(f.alpacaSubscribedSymbols||[]).length,stateLabel=(f.feedState==='streaming'||f.feedState==='alpaca-streaming'||f.feedState==='overnight-streaming')?liveLabelForSession(f.marketSession):f.feedState==='snapshot-live'?'SNAPSHOT':f.feedState==='reconnecting'?'RECONNECTING':sessionLabel(f.marketSession),light=(f.feedState==='streaming'||f.feedState==='alpaca-streaming'||f.feedState==='overnight-streaming')?'green':f.feedState==='reconnecting'?'red':'yellow';return `<section class="settings-section feed-diagnostics"><div class="section-heading-row"><div><h2>Live Data Diagnostics</h2><p>Detailed runtime health without creating additional subscriptions.</p></div>${statusDot(light,stateLabel)}</div><div class="diagnostic-grid"><div><span>Market Session</span><b>${esc(sessionLabel(f.marketSession))}</b></div><div><span>Finnhub WebSocket</span><b>${f.webSocketConnected?'Connected':'Disconnected'}</b><small>${count} active · ${num(f.finnhubMaxSymbols)||50} max · ${Math.max(0,(num(f.finnhubMaxSymbols)||50)-count)} available</small></div><div><span>Finnhub Last Trade</span><b>${lastFinnhub?timePair(lastFinnhub):'No recent trade'}</b><small>${esc(f.lastTradeSymbol||'')}</small></div><div><span>Alpaca IEX Fallback</span><b>${f.alpacaWebSocketConnected?'Connected':'Disconnected'}</b><small>${alpacaCount} active · ${num(f.alpacaMaxSymbols)||30} max · ${Math.max(0,(num(f.alpacaMaxSymbols)||30)-alpacaCount)} available</small></div><div><span>Alpaca IEX Last Update</span><b>${lastAlpacaStream?timePair(lastAlpacaStream):'No recent update'}</b><small>${esc(f.lastAlpacaStreamSymbol||'')}</small></div><div><span>Alpaca Snapshot / Overnight</span><b>${esc(titleCaseText(String(f.alpacaLiveFeed||'Idle')))}</b><small>${lastAlpaca?timePair(lastAlpaca):'No recent snapshot'} ${esc(f.lastAlpacaSymbol||'')}</small></div><div><span>Overnight Mode</span><b>${esc(titleCaseText(String(f.overnightDataMode||state?.settings?.overnightDataMode||'auto')))}</b><small>Live overnight: ${f.overnightLiveAvailable?'Available':'Not detected'}</small></div><div><span>Scanner</span><b>${esc(titleCaseText(runtime?.scanner?.status||'Idle'))}</b><small>${esc(runtime?.scanner?.message||'')}</small></div><div><span>Live Market Coverage</span><b>${num(f.liveSymbols)} live · ${(f.snapshotSymbols||[]).length} snapshot</b><small>${num(f.trackedSymbols)} tracked · Finnhub + Alpaca IEX + snapshot pool</small></div>${vixDiagnosticsCard()}</div></section>`}
