  const s=state?.settings||{},settingsSavedAt=num(state?.settingsSavedAt),savedLabel=settingsSavedAt?new Date(settingsSavedAt).toLocaleString('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' PT':'Not yet',activeAI=activeAIProvider();
