function optionsDashboardPulse(){const items=Object.values(runtime?.options||{}).filter(o=>['BULLISH','BEARISH'].includes(String(o.bias||''))).sort((a,b)=>(num(b.callVolume)+num(b.putVolume))-(num(a.callVolume)+num(a.putVolume))).slice(0,4);if(!items.length)return '';return `<section class="card options-pulse"><div class="card-head"><div><span class="eyebrow">Options Intelligence</span><h3>Material positioning context</h3><p>Horizon-aware context only · deterministic Scores unchanged.</p></div><span class="context-formula-note">${broadOptionsRegimeComponent()!=null?'Broad SPY/QQQ context correlated to Market Regime':'Ticker context only'}</span></div><div class="options-intel-list">${items.map(o=>`<button class="options-intel-row bias-${String(o.bias).toLowerCase()}" data-research="${esc(o.symbol)}" data-research-origin="dashboard"><span class="options-symbol"><b>${esc(o.symbol)}</b><i>${esc(titleCaseText(o.bias))}</i></span><span class="options-metrics"><em><small>P/C</small><b>${num(o.putCallVolume)?num(o.putCallVolume).toFixed(2):'—'}</b></em><em><small>IV</small><b>${num(o.averageIv)?pct(num(o.averageIv)*100):'—'}</b></em><em><small>ΔIV</small><b>${num(o.ivChange)?`${num(o.ivChange)>0?'+':''}${num(o.ivChange).toFixed(1)}pp`:'—'}</b></em><em><small>Expected</small><b>${num(o.expectedMove)?'$'+money(o.expectedMove):'—'}</b></em></span><span class="options-source">${esc(o.feed||o.state||'')} · ${o.updatedAt?ageText(Date.now()-num(o.updatedAt)):'No timestamp'}</span></button>`).join('')}</div></section>`}
function dashboardHeaderContext(){
 const health=headerDataHealth(),session=sessionLabel(marketSession()),events=(runtime?.macroEvents||[]).filter(x=>x.lifecycle!=='RESOLVED'),event=runtime?.eventMode?.active?runtime.eventMode:events[0],eventLabel=event?.name?`${event.name}${event.date?' · '+event.date:''}`:'No high-impact event loaded';
 return `<div class="dashboard-header-context"><span>${statusDot(health.tone==='running'?'green':health.tone==='degraded'?'yellow':'red',health.label)}<b>${esc(session)}</b></span><span><small>Next high-impact</small><b>${esc(eventLabel)}</b></span><span><small>Data</small><b>${esc(health.label.replace(/^DATA\s+/,''))}</b></span></div>`
}
function dashboardCard(kind){const cfg=deskCfg[kind],enabled=deskEnabled(kind),plans=enabled?topPlans(kind,99):[],p=plans[0];return `<section class="card summary-card ${enabled?'':'engine-off'}"><div class="card-head"><div><span class="eyebrow">Horizon Overview</span><h2>${cfg.title}</h2><p>${enabled?`${cfg.horizon} · ${plans.length} candidate${plans.length===1?'':'s'}`:'Engine off'}</p></div><button class="btn small ghost" data-jump="${kind}">Open</button></div>${enabled&&p?`<div class="top-pick dashboard-top-pick"><button class="top-pick-main" data-jump="${kind}" data-symbol="${p.sym}"><span><strong>${p.sym}</strong><small>${titleCaseText(actionState(p))} · ${Math.round(p.score)}/100 · ${tradeReadiness(p.sym,kind).status}</small></span><span class="right"><strong>$${money(p.price)}</strong><small>${esc(globalContextLine(p.sym,kind))}</small></span></button><button class="btn tiny ghost top-pick-research" data-research="${p.sym}" data-research-origin="dashboard">Research</button></div>`:enabled?'<div class="empty">No candidates.</div>':'<div class="empty">Turn on the engine to resume desk calculations.</div>'}</section>`}
function decisionQueuePlans(limit=5){const rows=[];for(const kind of ['day','swing','long']){if(!deskEnabled(kind))continue;for(const p of topPlans(kind,3)){const r=tradeReadiness(p.sym,kind),e=earningsIntelligence(p.sym),o=optionsFor(p.sym),priority=queuePriorityFor(p,kind,r);rows.push({...p,deskKind:kind,readiness:r,priority,e,o,keyDriver:keyDriverForPlan(p,kind),researchState:researchStateFor(p.sym)})}}rows.sort((a,b)=>({HIGH:3,MEDIUM:2,LOW:1}[b.priority]-({HIGH:3,MEDIUM:2,LOW:1}[a.priority]))||b.score-a.score);const unique=[];for(const p of rows){if(unique.some(x=>x.sym===p.sym))continue;unique.push(p);if(unique.length>=limit)break}return unique}
function syncLivePriorityHints(){if(window.__DEPULSE_TEST__||!state||!runtime)return;const symbols=decisionQueuePlans(5).map(x=>String(x.sym||'').toUpperCase()).filter(Boolean),sig=symbols.join('|'),now=Date.now();if(sig===lastLivePrioritySignature&&now-lastLivePrioritySentAt<20000)return;lastLivePrioritySignature=sig;lastLivePrioritySentAt=now;api('/api/live-priority',{symbols}).catch(()=>{if(lastLivePrioritySignature===sig){lastLivePrioritySignature='';lastLivePrioritySentAt=0}})}
function dashboardDecisionQueue(){const unique=decisionQueuePlans(5);return `<section class="card dashboard-decision-queue"><div class="card-head"><div><span class="eyebrow">Decision Queue</span><h2>What deserves attention now</h2><p>Technical Action stays deterministic; global, macro, options, earnings, SEC and Research context expose confirmations or contradictions.</p></div><span class="count-pill">${unique.length}</span></div><div class="decision-queue-list">${unique.map(p=>`<article class="decision-queue-card priority-${p.priority.toLowerCase()}"><div class="decision-queue-symbol"><span>${statusDot(setupLight(p),p.sym)}<b>${esc(p.sym)}</b><small>${p.deskKind==='long'?'Long':titleCaseText(p.deskKind)}</small></span><strong>${esc(titleCaseText(actionState(p)))}</strong></div><div class="decision-queue-fields"><span><small>Score</small><b>${Math.round(p.score)}/100</b></span><span><small>Priority</small><b>${p.priority}</b></span><span><small>Readiness</small><b>${esc(p.readiness.status)}</b></span><span><small>Research</small><b>${esc(p.researchState)}</b></span><span class="key-driver"><small>Key Driver</small><b>${esc(p.keyDriver)}</b></span><span class="risk-field"><small>Risk / Conflict</small><b>${esc(p.readiness.risks[0]||'No material conflict')}</b></span></div><details class="queue-why" data-expand-key="queue-${esc(p.sym)}-${p.deskKind}" open><summary>Why?</summary><ul><li>Technical: ${Math.round(p.score)}/100 · ${esc(titleCaseText(actionState(p)))}</li><li>Global/Macro: ${esc(globalContextLine(p.sym,p.deskKind))}</li><li>Options: ${esc(optionsContextLine(p.sym,p.deskKind))}</li><li>Earnings: ${esc(earningsCompactLine(p.sym))}</li>${latestEventReaction()&&p.deskKind==='day'?`<li>Macro reaction: ${esc(eventReactionLine())}</li>`:''}</ul></details><div class="button-row"><button class="btn tiny" data-jump="${p.deskKind}" data-symbol="${p.sym}">Open Desk</button><button class="btn tiny ghost" data-research="${p.sym}" data-research-origin="dashboard">Research</button></div></article>`).join('')||'<div class="empty">No enabled desk candidates yet.</div>'}</div></section>`}
function renderDashboard(){
 const tracked=allSymbols(),now=Date.now(),news=(runtime?.news||[]).filter(n=>tracked.some(s=>(n.symbols||[]).includes(s))&&num(n.datetime)>0&&now-num(n.datetime)*1000<=72*3600000).slice(0,2),earnings=(runtime?.earnings||[]).filter(e=>tracked.includes(String(e.symbol).toUpperCase())&&Math.abs(daysUntilDate(e.date)??999)<=14).sort((a,b)=>Math.abs(daysUntilDate(a.date)??999)-Math.abs(daysUntilDate(b.date)??999)).slice(0,2),filings=(runtime?.filings||[]).filter(f=>tracked.includes(String(f.symbol||'').toUpperCase())&&dateAgeDays(f.filedAt)<=30).slice(0,2);
 const col=(title,jump,rows,empty)=>`<div><div class="card-head compact"><h3>${title}</h3><button class="btn tiny ghost" data-jump="${jump}">View All</button></div>${rows||`<div class="empty">${empty}</div>`}</div>`;
 const catalysts=`<section class="card catalyst-pulse dashboard-catalyst-priority"><div class="card-head"><div><span class="eyebrow">Catalyst / Event Risk</span><h3>Catalyst Pulse · Fresh material context</h3><p>News ≤72h · filings ≤30d · earnings ±14d. Deep evidence stays in Research.</p></div></div><div class="catalyst-pulse-grid">${col('News','news',news.map(n=>`<button class="catalyst-pulse-row" data-url="${esc(n.url)}"><b>${esc(n.headline)}</b><small>${esc(n.source||'News')} · ${ageText(now-num(n.datetime)*1000)}</small></button>`).join(''),'No fresh mapped news.')}${col('Earnings','earnings',earnings.map(e=>`<button class="catalyst-pulse-row" data-research="${esc(e.symbol)}" data-research-origin="dashboard"><b>${esc(e.symbol)} · ${esc(earningsCompactLine(e.symbol))}</b><small>${dateOnly(e.date)} · ${esc(String(e.hour||'TBD').toUpperCase())}</small></button>`).join(''),'No earnings in the material window.')}${col('SEC','filings',filings.map(f=>`<button class="catalyst-pulse-row" data-url="${esc(f.url)}"><b>${esc(f.symbol)} · ${esc(secFilingMeaning(f))}</b><small>${esc(f.form)} · ${dateOnly(f.filedAt)}</small></button>`).join(''),'No fresh material filings.')}</div></section>`;
 return `<div class="page dashboard-page">${pageHead('Dashboard','Prioritized decisions first; every market-impacting capability is correlated, then shown only where horizon-relevant.','none',dashboardHeaderContext(),'none')}${marketContext()}${dashboardDecisionQueue()}${catalysts}<div class="summary-grid">${dashboardCard('day')}${dashboardCard('swing')}${dashboardCard('long')}</div>${optionsDashboardPulse()}${globalDriverPanel()}</div>`
}
function buildAIClientContext(sym,horizon=aiOriginHorizon){const target=String(sym||'').toUpperCase(),base={origin:aiOrigin,horizon,session:marketSession(),quoteState:quoteState(target),readiness:['day','swing','long'].includes(horizon)?tradeReadiness(target,horizon):null,globalContext:runtime?.global||{},derivedIntelligence:runtime?.intelligence||{},eventMode:runtime?.eventMode||{},options:optionsFor(target),earnings:earningsIntelligence(target),sec:secHorizonContext(target,horizon==='none'?'long':horizon),liquidity:runtime?.liquidity?.[target]||null,marketOpenFlags:runtime?.marketOpenFlags?.[target]||[],marketOpenCheckpoint:runtime?.marketOpenCheckpoint||null,catalystReaction:runtime?.catalystReactions?.[target]||null,providerIntelligence:runtime?.symbolIntelligence?.[target]||null,liveCoverage:runtime?.liveCoverage?.[target]||null,corporateActions:(runtime?.corporateActions||[]).filter(x=>String(x.symbol||'').toUpperCase()===target)};if(!canonicalResearchReady(target))return base;if(['day','swing','long'].includes(horizon))return {...base,deterministic:planFor(target,horizon),context:contextMetrics(target,horizon).must};return {...base,day:{score:planFor(target,'day').score,action:actionState(planFor(target,'day')),readiness:tradeReadiness(target,'day')},swing:{score:planFor(target,'swing').score,action:actionState(planFor(target,'swing')),readiness:tradeReadiness(target,'swing')},long:{score:planFor(target,'long').score,action:actionState(planFor(target,'long')),readiness:tradeReadiness(target,'long')}}}
function v14ProviderCards(){const s=state?.settings||{},input=(id,label,has,hint,optional='')=>`<article class="provider-card"><div class="provider-head"><div><h3>${label}</h3><span>${has?'Saved '+esc(hint||''):optional||'Not configured'}</span></div></div><div class="field"><label>API Key${optional?' · Optional':''}</label><input id="${id}-key" class="secret-input" type="password" autocomplete="off" placeholder="${has?'Leave blank to keep saved key':'Paste key'}"></div><div class="button-row"><button class="btn" data-test-provider="${id}">Save & Test</button><button class="btn ghost danger" data-clear-secret="${id}">Clear</button></div>${providerStatus(id)}</article>`;return `<section class="settings-section v14-data-providers"><div class="section-heading-row"><div><h2>Global, Macro & Options Data</h2><p>Premium-ready interfaces with real free/official/proxy fallback. Configuration stays here; operational truth stays in Maintenance.</p></div></div><div class="settings-grid-3"><div class="field"><label>Global Markets Provider Mode</label><select id="global-provider-mode"><option value="auto">AUTO · Recommended</option><option value="direct">Direct Only</option><option value="free-first">Free First</option><option value="proxy">Proxy Only</option></select></div><div class="field"><label>Options Data Mode</label><select id="options-data-mode"><option value="auto">AUTO · OPRA then Indicative</option><option value="opra">OPRA Only</option><option value="indicative">Indicative Only</option><option value="off">Off</option></select></div><label class="toggle"><span><b>High-Impact Macro Event Mode</b><small>Pre-warm data ~T−15; AI stays off the critical path.</small></span><input id="macro-event-mode" type="checkbox" ${s.macroEventModeEnabled!==false?'checked':''}></label></div><div class="provider-grid">${input('fred','FRED · Rates & Credit',state.hasFREDKey,state.fredKeyHint,'Free key')}${input('bls','BLS · CPI & Labor',state.hasBLSKey,state.blsKeyHint,'Registration key optional')}${input('eia','EIA · Energy',state.hasEIAKey,state.eiaKeyHint,'Free key')}${input('twelvedata','Twelve Data · Optional Direct Global',state.hasTwelveDataKey,state.twelveDataKeyHint,'Optional')}</div><article class="provider-card options-provider-card compact-options-provider"><div class="provider-head"><div><h3>Options Intelligence · Alpaca</h3><span>${state.hasAlpacaKey&&state.hasAlpacaSecret?'Uses saved Alpaca credentials':'Configure Alpaca above'}</span></div><span>Context only</span></div><div class="options-provider-body"><p>OPRA when entitled; AUTO falls back to real indicative option snapshots. No synthetic production values and no Options Trading Desk.</p><button class="btn options-capability-test" data-test-provider="options">Test Options Capability</button></div>${providerStatus('options')}</article></section>`}
function providerRegistryMarkup(){const rows=runtime?.providerRegistry||[],tone=s=>s==='AVAILABLE'?'positive':s==='PLAN LIMITED'?'warning':s==='TEMPORARILY UNAVAILABLE'?'negative':'muted';return `<div class="provider-capability-registry"><div class="section-heading-row compact"><div><h3>Provider Capability Registry</h3><p>Endpoint/plan truth is explicit. A configured API key never implies every capability is entitled.</p></div><span class="count-pill">${rows.length} checks</span></div><div class="provider-registry-grid">${rows.map(r=>`<article class="provider-registry-card"><div><b>${esc(r.provider)}</b><span class="${tone(r.status)}">${esc(r.status)}</span></div><strong>${esc(r.capability)}</strong><p>${esc(r.detail||'')}</p>${(r.uses||[]).length?`<small>Used by · ${esc(r.uses.join(' · '))}</small>`:''}</article>`).join('')||'<div class="empty">Capability registry initializes with the runtime.</div>'}</div></div>`}
function dataCapabilitiesMarkup(){const caps=runtime?.capabilities||[];return `<section class="settings-section data-capabilities"><div class="section-heading-row"><div><h2>Data Capabilities</h2><p>Operational truth: source, current mode, quality and upgrade readiness.</p></div><span class="count-pill">${caps.length} capabilities</span></div><div class="capability-grid">${caps.map(c=>`<div class="capability-card"><div><b>${esc(c.capability)}</b><span class="cap-status">${esc(c.status)}</span></div><strong>${esc(c.source)}</strong><small>${esc(c.mode||'')} ${c.freshness?'· '+esc(c.freshness):''}</small>${(c.details||[]).map(x=>`<p>${esc(x)}</p>`).join('')}</div>`).join('')||'<div class="empty">Capabilities initialize with the runtime.</div>'}</div>${providerRegistryMarkup()}</section>`}
function signalValidationMarkup(){const v=runtime?.signalValidation||{},sn=v.snapshots||[];return `<section class="settings-section signal-validation"><div class="section-heading-row"><div><h2>Signal Validation</h2><p>Outcomes correlate deterministic Action/Score with Research, Queue priority, Global/Macro, Options and Readiness. Evidence only; formulas never auto-change.</p></div><span class="count-pill">${sn.length} snapshots</span></div><div class="validation-table">${sn.slice(-10).reverse().map(x=>`<div class="validation-row"><div><b>${esc(x.symbol)} · ${esc(titleCaseText(x.horizon))}</b><small>${esc(x.action)} ${Math.round(num(x.score))}/100 · ${esc(x.readiness||'—')}</small></div><span>Research ${esc(x.researchState||'—')} · Queue ${esc(x.queuePriority||'—')}</span><span>${esc(x.keyDriver||x.globalContext||'Context pending')}</span><span>${x.outcomes?.['5D']!=null?'5D '+pct(x.outcomes['5D']):'Outcome pending'} · MFE ${num(x.mfe)?pct(x.mfe):'—'} · MAE ${num(x.mae)?pct(x.mae):'—'}</span></div>`).join('')||'<div class="empty">Snapshots are recorded from active desk decisions. Real outcomes populate only in Live mode from later historical bars.</div>'}</div></section>`}
function updateMacroEventBanner(){const el=$('#macro-event-banner');if(!el)return;const m=runtime?.eventMode||{};if(!m.active||!m.startsAt){el.setAttribute('aria-hidden','true');el.textContent='';return}const sec=Math.round((num(m.startsAt)-Date.now())/1000),abs=Math.abs(sec),min=Math.floor(abs/60),rem=abs%60,clock=`${min}:${String(rem).padStart(2,'0')}`;el.textContent=sec>0?`HIGH-IMPACT EVENT · ${m.name||'Macro event'} in ${clock} · market data prioritized`:`HIGH-IMPACT EVENT · ${m.name||'Macro event'} released ${clock} ago · reaction mode active`;el.setAttribute('aria-hidden','false')}
function recordVisibleSignal(){if(!['day','swing','long'].includes(page))return;const sym=selected[page];if(!sym)return;const p=planFor(sym,page),r=tradeReadiness(sym,page),key=`${sym}:${page}:${Math.floor(Date.now()/1800000)}`;window.__v14SignalKeys=window.__v14SignalKeys||new Set();if(window.__v14SignalKeys.has(key))return;window.__v14SignalKeys.add(key);api('/api/signal-validation/record',{symbol:sym,horizon:page,timestamp:Date.now(),price:p.price,score:p.score,action:actionState(p),readiness:r.status,marketRegime:marketRegimeFor(page).label,globalContext:runtime?.global?.tone||'',optionsBias:optionsFor(sym)?.bias||'',eventRisk:p.eventRisk,researchState:researchStateFor(sym),queuePriority:queuePriorityFor(p,page,r),keyDriver:keyDriverForPlan(p,page),contradictions:r.risks||[]}).catch(()=>window.__v14SignalKeys.delete(key))}
